  ammo:     '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M4 20 L 18 6 M 14 6 H 18 V 10 M 6 18 L 4 20 L 6 22"/></svg>',
  ring1:    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><circle cx="12" cy="14" r="6"/><path d="M9 6 L 12 9 L 15 6"/></svg>',
  ring2:    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><circle cx="12" cy="14" r="6"/><path d="M9 6 L 12 9 L 15 6"/></svg>',
