  companion:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><circle cx="8" cy="11" r="3"/><circle cx="16" cy="11" r="3"/><circle cx="6" cy="6" r="2"/><circle cx="18" cy="6" r="2"/><ellipse cx="12" cy="18" rx="5" ry="3"/></svg>',
