/* ════════════════════════════════════════════════════════
   INVENTORY REWORK + LOADOUT PRESETS — additive
   Wraps existing renderInventory + onItemTap. No combat edits.
   ════════════════════════════════════════════════════════ */

/* ───── State init ───── */
G.loadouts = G.loadouts || [
  {name:'Combat',  icon:'⚔️', equipment:{}, tools:{}, foodSlot:null, set:false},
  {name:'Mining',  icon:'⛏️', equipment:{}, tools:{}, foodSlot:null, set:false},
  {name:'Cooking', icon:'🍳', equipment:{}, tools:{}, foodSlot:null, set:false},
  {name:'Custom',  icon:'⭐', equipment:{}, tools:{}, foodSlot:null, set:false},
];
window._invFilter = 'all';
window._invSort = 'recent';
window._invSearch = '';
window._invSelectMode = false;
window._invSelected = new Set();
window._activeLoadout = -1;

/* ───── Helpers ───── */
function _itemCategory(it){
  if(!it) return 'mat';
  if(it.type === 'weapon') return 'gear';
  if(it.type === 'armor' || it.type === 'jewelry' || it.type === 'ammo' || it.type === 'companion') return 'gear';
  if(it.heals) return 'food';
  if(it.seed) return 'seed';
  if(it.buryXp) return 'bone';
  /* bars / ore / planks / logs by name suffix */
  const n = (it.n || '').toLowerCase();
  if(/bar$/.test(n)) return 'bar';
  if(/ore$/.test(n) || /coal$/.test(n)) return 'mat';
  if(/log$/.test(n) || /plank$/.test(n)) return 'plank';
  return 'mat';
}
function _itemTier(id){
  const tiers=['bronze','iron','steel','mithril','adamant','rune','dragon'];
  for(let i=0;i<tiers.length;i++){ if(String(id).startsWith(tiers[i]+'_')) return i+1; }
  return 0;
}
function _shortName(name){
  return String(name||'').split(' ')[0];
}
function _eqStatsTotals(){
  const s = {atk:0, str:0, def:0, hp:0};
  if(typeof getEquipmentStats === 'function'){
    const r = getEquipmentStats();
    s.atk = r.atkB || r.attackBonus || 0;
    s.str = r.strB || r.strengthBonus || 0;
    s.def = r.defB || r.defenseBonus || 0;
    s.hp  = r.hpB  || r.hitpointsBonus || 0;
  } else if(G.equipment){
    Object.values(G.equipment).forEach(id=>{
      const it = ITEMS[id]; if(!it) return;
      s.atk += it.atkB||0; s.str += it.strB||0; s.def += it.defB||0; s.hp += it.hpB||0;
    });
  }
  return s;
}

/* ───── Loadout actions ───── */
function saveLoadout(idx){
  const l = G.loadouts[idx]; if(!l) return;
  l.equipment = {...G.equipment};
  l.tools = {...(G.tools||{})};
  l.foodSlot = G.foodSlot || null;
  l.set = true;
  saveLocal();
  notify(`💾 Saved loadout: ${l.name}`, 'info');
  renderInvNew();
}
function applyLoadout(idx){
  const l = G.loadouts[idx]; if(!l || !l.set){ notify('Slot is empty — long-press to save current kit', 'kill'); return; }
  /* Equipment: items currently equipped that aren't in the preset go to bag */
  const newEq = {};
  Object.keys(G.equipment).forEach(slot=>{
    const cur = G.equipment[slot];
    const target = l.equipment[slot] || null;
    /* if current slot has an item, return it to bag */
    if(cur) addItem(cur, 1);
    /* if target item exists in bag, take from bag */
    if(target){
      /* b246: a loadout can't sneak past the wield gate — but items you've worn
         are grandfathered, so a legitimately-saved kit re-applies cleanly. */
      if(hasItem(target, 1) && (typeof canWield!=='function' || canWield(target).ok)){
        removeItem(target, 1);
        newEq[slot] = target;
        G.wieldGrandfather = G.wieldGrandfather || {}; G.wieldGrandfather[target] = true;
      } else {
        newEq[slot] = null;
      }
    } else {
      newEq[slot] = null;
    }
  });
  G.equipment = newEq;
  /* Tools: held tools, not in inventory — just copy refs that exist in ITEMS */
  if(G.tools && l.tools){
    Object.keys(G.tools).forEach(slot=>{
      const target = l.tools[slot];
      if(target && ITEMS[target]) G.tools[slot] = target;
    });
  }
  /* Food slot */
  if(l.foodSlot && hasItem(l.foodSlot, 1)) G.foodSlot = l.foodSlot;
  else if(!l.foodSlot) G.foodSlot = null;
  window._activeLoadout = idx;
  saveLocal();
  notify(`✓ Applied loadout: ${l.name}`, 'levelup');
  refreshAll();
}
function renameLoadout(idx){
  const l = G.loadouts[idx]; if(!l) return;
  const nm = prompt(`Rename "${l.name}" to:`, l.name);
  if(nm && nm.trim()){ l.name = nm.trim().slice(0,18); saveLocal(); renderInvNew(); }
}
function clearLoadout(idx){
  const l = G.loadouts[idx]; if(!l) return;
  if(!confirm(`Clear loadout "${l.name}"?`)) return;
  l.equipment = {}; l.tools = {}; l.foodSlot = null; l.set = false;
  saveLocal(); renderInvNew();
}

/* ───── Filters / search / sort ───── */
const _CATEGORIES = [
  {id:'all',     label:'All',      test:()=>true},
  {id:'weapons', label:'Weapons',  test:it=>it && it.type==='weapon'},
  {id:'armor',   label:'Armor',    test:it=>it && (it.type==='armor' || it.type==='jewelry' || it.type==='ammo' || it.type==='companion')},
  {id:'food',    label:'Food',     test:it=>it && it.heals},
  {id:'seeds',   label:'Crops',    test:it=>it && (it.seed || it.crop)},
  {id:'bones',   label:'Bones',    test:it=>it && (it.buryXp || /bones?$/.test(it.n||''))},
  {id:'mat',     label:'Materials',test:it=>it && !it.type && !it.heals && !it.seed && !it.buryXp},
];
function _itemCategoryDisplay(it){
  if(!it) return 'mat';
  if(it.type === 'weapon') return 'weapon';
  if(it.type === 'armor' || it.type === 'jewelry' || it.type === 'ammo' || it.type === 'companion') return 'gear';
  if(it.heals) return 'food';
  if(it.seed) return 'seed';
  if(it.buryXp) return 'bone';
  if(/(_bar|_ore|_log|_plank)$/.test(it.id||'') || /Bar|Ore|Log|Plank/.test(it.n||'')) return 'mat';
  return 'mat';
}
function _filteredItems(srcDict){
  const cat = _CATEGORIES.find(c=>c.id === window._invFilter) || _CATEGORIES[0];
  const search = (window._invSearch||'').toLowerCase().trim();
  let arr = Object.entries(srcDict).filter(([id,q])=>{
    if(q <= 0) return false;
    const it = ITEMS[id]; if(!it) return false;
    if(!cat.test(it)) return false;
    if(search && !it.n.toLowerCase().includes(search)) return false;
    return true;
  });
  /* sort */
  switch(window._invSort){
    case 'name': arr.sort((a,b)=>(ITEMS[a[0]]?.n||'').localeCompare(ITEMS[b[0]]?.n||'')); break;
    case 'value':arr.sort((a,b)=>(ITEMS[b[0]]?.v||0)-(ITEMS[a[0]]?.v||0)); break;
    case 'qty':  arr.sort((a,b)=>b[1]-a[1]); break;
    /* 'recent' = insertion order, no sort */
  }
  return arr;
}

/* ════════════════════════════════════════════════════════
   b224 — ONE description of a food, for every surface that uses one.

   Beta feedback: "eating food is confusing." Playing it back, the confusion
   was not subtle — there was no Eat button. Left-clicking a Provision opened
   this flyout and offered `Set Auto-eat` / `Sell 1` / `Sell All`; the `Eat 1`
   button next to them was gated behind `typeof eatItem === 'function'` and
   `eatItem` has never existed in this codebase, so it has never once
   rendered. The only working manual-eat path was a right-click context menu.

   Worse, the prominent button was wrong three ways at once:
     1. it wrote G.foodSlot, a field the engine stopped reading in b134, so
        it configured nothing;
     2. it appeared on Feasts & Draughts, which b220 made permanently
        ineligible for auto-eat — the combat picker got that filter, this
        flyout did not;
     3. auto-eat is a 5,000g Store trait (b217) that a new player does not
        own, and nothing said so. b217's own comment reads "early game is
        manual eating (click food in combat)" — that click target was never
        built.

   So the fix is comprehension, in the UI, at the point of use (b217 rule):
   every surface that talks about a food now reads its wording from here, and
   cannot invent its own.
   ════════════════════════════════════════════════════════ */
const _FOOD_KIND_META_FALLBACK = {
  provision:{label:'Provision', verb:'Eat',   blurb:'Healing food. Auto-eat can use this.'},
  feast:    {label:'Feast',     verb:'Use',   blurb:'Eaten for a timed buff. Auto-eat never spends it.'},
  draught:  {label:'Draught',   verb:'Drink', blurb:'Drunk for a timed buff. Auto-eat never spends it.'},
};
const _FOOD_VERB_PAST = {Eat:'Ate', Drink:'Drank', Use:'Used'};
/* Mirrors data/items.js foodKindOf for the boot window before the ESM data
   module lands. Same rule, one line — cheaper than a food UI that goes blank
   mid-boot. */
function _foodKindOf(it){
  if(typeof window.foodKindOf === 'function') return window.foodKindOf(it);
  if(!it || typeof it !== 'object') return null;
  const cls = (it.foodClass==='healing'||it.foodClass==='buff') ? it.foodClass : (it.heals ? 'healing' : null);
  if(!cls) return null;
  if(cls === 'healing') return 'provision';
  return /\b(elixir|draught|draft|potion|brew|tonic|cordial|tea)\b/i.test(it.n||'') ? 'draught' : 'feast';
}
/* → {kind,label,verb,verbPast,blurb,heals,healText,buffText,autoEatable} or null */
function foodUseInfo(id){
  const it = (typeof ITEMS !== 'undefined') ? ITEMS[id] : null;
  if(!it) return null;
  const kind = _foodKindOf(it);
  if(!kind) return null;
  const meta = ((window.FOOD_KIND_META && window.FOOD_KIND_META[kind]) || _FOOD_KIND_META_FALLBACK[kind]);
  const heals = it.heals || 0;
  let buffText = '';
  if(it.buff && it.buff.type){
    const bd = (window.BUFFS_DEF || {})[it.buff.type];
    const name = bd ? bd.label : String(it.buff.type).replace(/_/g,' ');
    const mins = Math.round((it.buff.durationMs||0)/60000);
    buffText = '+' + (it.buff.magnitude||0) + '% ' + name + (mins ? ' for ' + mins + ' min' : '');
  }
  return {
    id, kind,
    label: meta.label, verb: meta.verb, verbPast: _FOOD_VERB_PAST[meta.verb] || meta.verb,
    blurb: meta.blurb,
    heals, healText: heals ? ('Heals ' + heals) : '',
    buffText,
    autoEatable: kind === 'provision',
  };
}
window.foodUseInfo = foodUseInfo;

/* The best Provision in the bag — the same "biggest heal you own" rule
   HearthriseAuto.maybeAutoEat() falls back to, so the combat Eat button and
   auto-eat never disagree about what your healing food is. */
function bestProvisionId(){
  if(typeof G === 'undefined' || !G.inventory || typeof ITEMS === 'undefined') return null;
  const configured = (window.HearthriseAuto && window.HearthriseAuto.getEat)
    ? (window.HearthriseAuto.getEat().foodId || null) : null;
  if(configured && (G.inventory[configured]||0) > 0 && _foodKindOf(ITEMS[configured]) === 'provision') return configured;
  let bestId = null, bestHeals = -1;
  for(const id in G.inventory){
    if((G.inventory[id]||0) <= 0) continue;
    const it = ITEMS[id];
    if(_foodKindOf(it) !== 'provision') continue;
    if((it.heals||0) > bestHeals){ bestId = id; bestHeals = it.heals||0; }
  }
  return bestId;
}
window.bestProvisionId = bestProvisionId;

/* Is auto-eat currently pointed at this exact item (and switched on)? */
function _autoEatUsesThis(id){
  const cfg = (window.HearthriseAuto && window.HearthriseAuto.getEat) ? window.HearthriseAuto.getEat() : null;
  return !!(cfg && cfg.enabled && cfg.foodId === id);
}

/* Eat from a UI surface: consume, then refresh what the player is looking at.
   eatFood() owns the rules and the toast; this owns the repaint. */
window.eatFromInventory = function(id){
  const ok = (typeof window.eatFood === 'function') ? window.eatFood(id) : false;
  if(ok && typeof closeInvDetail === 'function') closeInvDetail();
  if(typeof window._renderInvFancy === 'function') setTimeout(window._renderInvFancy, 0);
  if(typeof updateTopbar === 'function') updateTopbar();
  return ok;
};
/* The combat screen's manual heal. */
window.eatBestProvision = function(){
  const id = bestProvisionId();
  if(!id){ notify('No healing food in your bag — cook fish or bake bread.','kill'); return false; }
  return window.eatFromInventory(id);
};
/* Route auto-eat config through the ONE writer the engine reads (b134).
   The old inline `G.foodSlot='x'` handler wrote a field nothing consumes. */
window.setAutoEatFood = function(id){
  const info = foodUseInfo(id);
  if(!info || !info.autoEatable){
    notify('Auto-eat only uses Provisions — ' + ((ITEMS[id]||{}).n || id) + ' must be eaten by hand.','kill');
    return false;
  }
  if(typeof hasTrait === 'function' && !hasTrait('auto_eat')){
    notify('Auto-eat is locked — unlock it in the Store.','kill');
    return false;
  }
  G.foodSlot = id;   /* kept in step for old saves / loadout presets */
  if(window.HearthriseAuto && window.HearthriseAuto.setEat){
    window.HearthriseAuto.setEat({foodId:id, enabled:true});
  }
  notify('Auto-eat set to ' + ((ITEMS[id]||{}).n || id) + '.','info');
  if(typeof renderCombat === 'function' && G.activeMonster) renderCombat();
  return true;
};
/* Combat picker onchange — "" is the explicit Off option, not a bad item id. */
window.setCombatAutoEat = function(value){
  if(!value){
    G.foodSlot = null;
    if(window.HearthriseAuto && window.HearthriseAuto.setEat){
      window.HearthriseAuto.setEat({foodId:null, enabled:false});
    }
    notify('Auto-eat off.','info');
    if(typeof renderCombat === 'function' && G.activeMonster) renderCombat();
    return false;
  }
  return window.setAutoEatFood(value);
};

/* b267: Auto-eat food PICKER — a compact modal so the choice is reachable from
   the always-visible arena HUD (the old in-combat <select> sat below the fold on
   landscape; paione: "on landscape I don't have the option to select food").
   Lists every eligible Provision + an Off option; picking one sets it and closes. */
window.openAutoEatPicker = function(){
  if(typeof G==='undefined'||!G) return;
  /* b294: the eligibility helper `_autoEatOk` is a const scoped inside the
     combat-render function, NOT visible here — this is a separate top-level
     function. Referencing it made `typeof _autoEatOk` resolve to 'undefined',
     so the filter rejected EVERY item and the picker always claimed the bag
     held no Provisions (tester: "won't let me pick food … says no provisions").
     Use the same authority the engine eats from, inline, so the two can't drift. */
  const _aeOk = (id)=> (window.HearthriseAuto && typeof window.HearthriseAuto.isAutoEatable==='function')
    ? window.HearthriseAuto.isAutoEatable(ITEMS[id])
    : !!(ITEMS[id] && ITEMS[id].heals && ITEMS[id].foodClass!=='buff');
  const foods = Object.entries(G.inventory||{}).filter(([id])=> _aeOk(id));
  const cur = (window.HearthriseAuto && window.HearthriseAuto.getEat) ? (window.HearthriseAuto.getEat().foodId||null) : null;
  const esc = s => String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  /* b341 — DO NOT OFFER A CHOICE THAT WILL BE REFUSED.
     setAutoEatFood() has always rejected every pick when the Auto-Eat trait is
     not owned, but this picker rendered its rows live anyway: tapping one closed
     the overlay as if it had taken, `foodId` stayed null, the only contradiction
     was a toast that expires, and re-opening showed "— Off —" still marked
     `is-on`. The player is told they failed by an artifact that is gone in ten
     seconds while the surface itself keeps insisting nothing happened.
     Locked now means locked ON THE ROWS, with the reason stated in place. */
  const _locked = (typeof hasTrait === 'function') && !hasTrait('auto_eat');
  const _act = (arg)=> _locked ? '' : ` onclick="setCombatAutoEat(${arg});closeAutoEatPicker()"`;
  const rows = foods.map(([id,q])=>{
    const it=ITEMS[id]; if(!it) return '';
    const on = !_locked && cur===id;
    return `<button class="aep-row${on?' is-on':''}"${_locked?' disabled':''}${_act(`'${id}'`)}>
        <span class="aep-ic">${it.icon||''}</span>
        <span class="aep-nm">${esc(it.n)}</span>
        <span class="aep-heal">+${it.heals||0} HP</span>
        <span class="aep-q">×${(q||0).toLocaleString()}</span>
      </button>`;
  }).join('');
  const offRow = `<button class="aep-row${(!_locked && !cur)?' is-on':''}"${_locked?' disabled':''}${_act(`''`)}>
      <span class="aep-ic">—</span><span class="aep-nm">Off — heal by hand</span></button>`;
  const empty = _locked
    ? '<div class="aep-empty">Auto-eat is locked. Unlock it in the Store to choose a food — until then, heal by hand with the Eat button beside your champion.</div>'
    : (foods.length ? '' : '<div class="aep-empty">No Provisions in your bag. Cook fish or bake bread first — Feasts &amp; Draughts are eaten by hand only.</div>');
  let ov = document.getElementById('aep-overlay');
  if(!ov){
    ov = document.createElement('div'); ov.id='aep-overlay'; ov.className='aep-overlay';
    document.body.appendChild(ov);
    ov.addEventListener('click', e=>{ if(e.target===ov) window.closeAutoEatPicker(); });
  }
  ov.innerHTML = `<div class="aep-modal" role="dialog" aria-label="Choose auto-eat food">
      <div class="aep-head"><span>Auto-eat food</span><button class="aep-x" onclick="closeAutoEatPicker()" aria-label="Close">✕</button></div>
      <div class="aep-body">${empty}${offRow}${rows}</div>
      <div class="aep-note">Spends one Provision when your HP drops low. Feasts &amp; Draughts are never auto-eaten.</div>
    </div>`;
  ov.style.display = 'flex';
};
window.closeAutoEatPicker = function(){ const ov=document.getElementById('aep-overlay'); if(ov) ov.style.display='none'; };

/* ───── Item detail flyout ───── */
function openInvDetail(id){
  const it = ITEMS[id]; if(!it) return;
  const qty = G.inventory[id] || G.bank[id] || 0;
  /* b224: "food" told the player nothing — a Cooked Shrimp and a Void Banquet
     both read `FOOD` under the name while behaving completely differently.
     Name the kind instead: Provision / Feast / Draught. */
  const _food = foodUseInfo(id);
  const cat = _food ? _food.label : _itemCategory(it);
  const d = document.getElementById('inv-detail-overlay') || (function(){
    const el = document.createElement('div');
    el.id = 'inv-detail-overlay';
    el.className = 'inv-detail';
    el.addEventListener('click',e=>{ if(e.target===el) el.classList.remove('show'); });
    document.body.appendChild(el);
    return el;
  })();
  /* Stats grid for gear/tools, otherwise show value/qty */
  const stats = [];
  stats.push(`<div><b>${qty.toLocaleString()}</b><span>quantity</span></div>`);
  stats.push(`<div><b>🪙 ${(it.v||0).toLocaleString()}</b><span>value each</span></div>`);
  /* b226: for a raw material the book value and the vendor's bid are different
     numbers, so say both. A player who sees "1,400 value" and is paid 280 has
     been told a half-truth; a player who is told the vendor lowballs raws has
     been handed the reason the player market exists. */
  if(it.raw) stats.push(`<div><b>🪙 ${vendorPrice(id).toLocaleString()}</b><span>vendor pays</span></div>`);
  if(it.atkB) stats.push(`<div><b>+${it.atkB}</b><span>attack</span></div>`);
  if(it.strB) stats.push(`<div><b>+${it.strB}</b><span>strength</span></div>`);
  if(it.defB) stats.push(`<div><b>+${it.defB}</b><span>defense</span></div>`);
  /* b224: state the effect in plain words. A buff item used to show only its
     heal number, so its whole reason to exist was invisible at the point of use. */
  if(_food && _food.heals) stats.push(`<div><b>+${_food.heals} HP</b><span>${_food.kind==='provision'?'heals when eaten':'also heals'}</span></div>`);
  else if(it.heals) stats.push(`<div><b>+${it.heals}</b><span>heals</span></div>`);
  if(_food && _food.buffText) stats.push(`<div><b>${_food.buffText.split(' for ')[0]}</b><span>${_food.buffText.includes(' for ')?'for '+_food.buffText.split(' for ')[1]:'timed buff'}</span></div>`);
  if(it.speed != null) stats.push(`<div><b>+${Math.round((it.speed||0)*100)}%</b><span>tool speed</span></div>`);
  if(it.smithSpeed != null) stats.push(`<div><b>+${Math.round((it.smithSpeed||0)*100)}%</b><span>smith speed</span></div>`);
  if(it.doubleCook != null) stats.push(`<div><b>+${Math.round((it.doubleCook||0)*100)}%</b><span>double-cook</span></div>`);
  if(it.noBurn != null) stats.push(`<div><b>+${Math.round((it.noBurn||0)*100)}%</b><span>no-burn</span></div>`);
  if(it.weaponType) stats.push(`<div><b>${it.weaponType}</b><span>weapon type</span></div>`);
  if(it.reqSkill && it.reqLv) stats.push(`<div><b>${SKILLS_DEF[it.reqSkill]?.name||it.reqSkill} ${it.reqLv}</b><span>required</span></div>`);

  /* Action buttons — detect by type/heals/seed/buryXp instead of kind */
  const acts = [];
  const isEquippable = it && (it.type==='weapon' || it.type==='armor' || it.type==='jewelry' || it.type==='ammo' || it.type==='companion' || it.kind==='gear' || it.kind==='tool');
  if(isEquippable){
    if(typeof equipItem === 'function')           acts.push(`<button class="btn btn-primary" onclick="equipItem('${id}');closeInvDetail();setTimeout(renderInvNew,0)">Equip</button>`);
    else if(typeof equipGear === 'function')      acts.push(`<button class="btn btn-primary" onclick="equipGear('${id}');closeInvDetail();setTimeout(renderInvNew,0)">Equip</button>`);
  }
  /* b224: food. The action IS the point of this screen — Eat/Drink/Use is the
     primary button, and it is honest about what it will do. See foodUseInfo(). */
  /* Bank-only stacks open this same flyout, and eatFood() reads the bag — so
     only offer the verb when there is something in the bag to spend. */
  if(_food && (G.inventory[id]||0) > 0){
    const atFull = typeof G.playerHp === 'number' && typeof G.playerMaxHp === 'number'
      && G.playerHp >= G.playerMaxHp;
    if(_food.kind === 'provision' && atFull){
      /* Honest dead-end instead of silently burning the item for nothing —
         "I clicked it and nothing happened" was half the reported confusion. */
      acts.push(`<button class="btn" disabled title="Your health is already full">Already at full health</button>`);
    } else {
      const sub = _food.kind === 'provision'
        ? (_food.healText ? ' — ' + _food.healText : '')
        : (_food.buffText ? ' — ' + _food.buffText : '');
      acts.push(`<button class="btn btn-primary" onclick="eatFromInventory('${id}')">${_food.verb}${sub}</button>`);
    }
    /* Auto-eat is offered only where it is true: a Provision, and a trait the
       player actually owns. Everything else gets a sentence, not a button. */
    if(_food.autoEatable && typeof hasTrait === 'function' && hasTrait('auto_eat')
       && !_autoEatUsesThis(id)){
      acts.push(`<button class="btn" onclick="setAutoEatFood('${id}');closeInvDetail()">Set as auto-eat food</button>`);
    }
  }
  if(it.kind === 'upgrade' || it.upgradesTo){
    if(typeof openUpgradePicker === 'function') acts.push(`<button class="btn btn-primary" onclick="openUpgradePicker('${id}');closeInvDetail()">Apply Kit</button>`);
  }
  if(it.seed){
    acts.push(`<button class="btn" onclick="showTab('farming');closeInvDetail()">Open Farm</button>`);
  }
  if(it.buryXp){
    acts.push(`<button class="btn" onclick="if(typeof buryBones==='function'){buryBones('${id}');}else{G.skills.prayer=(G.skills.prayer||0)+${it.buryXp};removeItem('${id}',1);notify('Buried (+${it.buryXp} prayer XP)','info');}closeInvDetail();renderInvNew()">Bury</button>`);
  }
  if(qty > 0){
    /* b240: sell-lock. A locked item shows no sell buttons — just Unlock — so an
       accidental tap can't get through. Vendorable items get a Lock button. */
    if(isItemLocked(id)){
      acts.push(`<button class="btn" disabled title="Locked — protected from selling">Locked</button>`);
      acts.push(`<button class="btn" onclick="toggleItemLock('${id}');openInvDetail('${id}')">Unlock</button>`);
    } else {
      if(vendorPrice(id) > 0){
        acts.push(`<button class="btn" onclick="invSellOne('${id}');closeInvDetail()">Sell 1 (${vendorPrice(id)}🪙)</button>`);
        if(qty > 1) acts.push(`<button class="btn btn-danger" onclick="invSellAll('${id}')">Sell All ${qty} (${(vendorPrice(id)*qty).toLocaleString()}🪙)</button>`);
      }
      acts.push(`<button class="btn" onclick="toggleItemLock('${id}');openInvDetail('${id}')" title="Protect this item from being sold">Lock</button>`);
    }
    /* b311: Buy-Back moved to the Local Shop (where you sell to the vendor) — it
       no longer clutters every item's detail popup. */
    if(typeof bankItem === 'function') acts.push(`<button class="btn" onclick="bankItem('${id}',${qty});closeInvDetail()">→ Bank</button>`);
  }

  /* b224: one sentence saying what this food is for, plus the honest status of
     auto-eat. b217's rule is that comprehension gets fixed in the UI, not in a
     tutorial — so the screen that offers the button also explains the button. */
  let foodNote = '';
  if(_food){
    const bits = [_food.blurb];
    if(_food.autoEatable){
      if(typeof hasTrait === 'function' && !hasTrait('auto_eat')){
        const _tae=(window.TRAITS&&window.TRAITS.auto_eat)||{cost:100,currency:'marks'};const cost=_tae.cost.toLocaleString()+(_tae.currency==='marks'?' Bounty Marks':'g');
        bits.push(`You have not unlocked Auto-Eat yet (${cost} in the Store) — for now, heal by hand from here or the Combat screen.`);
      } else if(_autoEatUsesThis(id)){
        bits.push('Auto-eat is currently using this food.');
      }
    }
    foodNote = `<div class="inv-detail-note">${bits.join(' ')}</div>`;
  } else if(it.note){
    /* b225: the same slot for a non-food item that needs one sentence of
       explanation. Burnt Food is the first: without this, a player who has
       just lost a shrimp to the fire opens a mystery item worth 1 gold. */
    foodNote = `<div class="inv-detail-note">${it.note}</div>`;
  }

  /* b242 (itemization Wave 2 — "explain everything on hover/tap"): the flavour
     line + where it comes from + what it crafts into, from the reverse index.
     Each is optional — an item with no data simply shows no line. */
  const _desc = (typeof window.itemDesc==='function') ? window.itemDesc(id) : '';
  const _src  = (typeof window.itemSourceLine==='function') ? window.itemSourceLine(id) : '';
  const _used = (typeof window.itemUsedInLine==='function') ? window.itemUsedInLine(id) : '';
  const descHtml = _desc ? `<div class="inv-detail-desc">${_desc}</div>` : '';
  let infoBlock = '';
  if(_src)  infoBlock += `<div class="inv-detail-info"><b>Source</b><span>${_src}</span></div>`;
  if(_used) infoBlock += `<div class="inv-detail-info"><b>Used in</b><span>${_used}</span></div>`;

  d.innerHTML = `<div class="inv-detail-card">
    <div class="inv-detail-close" onclick="closeInvDetail()">✕</div>
    <div class="inv-detail-head">
      <div class="inv-detail-icon">${it.icon||'❓'}</div>
      <div>
        <div class="inv-detail-name">${it.n}</div>
        <div class="inv-detail-meta">${cat}${it.slot?' · '+it.slot:''}${it.weaponType?' · '+it.weaponType:''}${_itemTier(id)?' · T'+_itemTier(id):''}</div>
      </div>
    </div>
    ${descHtml}
    <div class="inv-detail-stats">${stats.join('')}</div>
    ${infoBlock}
    ${foodNote}
    <div class="inv-detail-actions">${acts.join('')}</div>
  </div>`;
  d.classList.add('show');
}
function closeInvDetail(){
  document.getElementById('inv-detail-overlay')?.classList.remove('show');
}

/* ════════════════════════════════════════════════════════════════
   b226 — vendorPrice(): what the NPC vendor BIDS, in one place.
   (docs/design/pacing-overhaul.md §6.1.)

   Raw materials fetch VENDOR_RAW_RATE × their book value; everything else
   fetches the book value. `ITEMS[id].v` is NOT touched — it stays the number
   market listings, recipe costing, chest payouts and the collection log all
   read, so nobody's bank is revalued and nothing already earned is reached
   into. Only the vendor's bid, and only from now on.

   Gathering throughput is roughly flat (~300 items/h at every tier) while `v`
   climbs 2.77× per material tier, so a maxed miner vendoring Dawnstone
   out-earned the King renown reward — 300,000 gold, the eleventh of twelve
   ranks — every 32 minutes, WHILE ASLEEP. Beyond the arithmetic this puts
   three systems back in their proper roles: gathering is the material faucet,
   the artisan skills are the gold path, and the player market becomes the
   best price for raws, because another player will pay more than 20% for
   something they actually need.

   ONE choke-point, mirroring applyGoldFind(). Every sell path in the game —
   the bag's Sell 1 / Sell All / Sell Selected, the context menu, the quick-
   sell slider, the sell-junk sweep and the old inventory tap — reads this.
   A price that differs by which button you pressed is not a price.
   ════════════════════════════════════════════════════════════════ */
const VENDOR_RAW_RATE = 0.20;
function vendorPrice(id){
  const it = (typeof ITEMS==='object' && ITEMS) ? ITEMS[id] : null;
  if(!it) return 0;
  const v = Number(it.v) || 0;
  if(v <= 0) return 0;
  /* Floored at 1: a raw worth anything at all is still worth something, and a
     0g bid reads as "this item is broken" rather than "this is cheap". */
  return it.raw ? Math.max(1, Math.floor(v * VENDOR_RAW_RATE)) : v;
}
window.VENDOR_RAW_RATE = VENDOR_RAW_RATE;
window.vendorPrice = vendorPrice;

/* Sell helpers — wrap existing logic if available, else simple */
function invSellOne(id){
  const it = ITEMS[id]; if(!it) return;
  if(isItemLocked(id)){ notify(`${it.n} is locked — unlock it first`,'kill'); return; }   // b240
  if((G.inventory[id]||0) <= 0){ notify('Nothing to sell','kill'); return; }
  const price = vendorPrice(id);
  G.gold = (G.gold||0) + price;
  removeItem(id, 1);
  recordVendorSale(id, 1, price);   // b240: undoable
  notify(`Sold 1× ${it.n} (+${price}🪙)`,'loot');
  updateTopbar(); renderInvNew();
}
function invSellAll(id){
  const it = ITEMS[id]; if(!it) return;
  if(isItemLocked(id)){ notify(`${it.n} is locked — unlock it first`,'kill'); return; }   // b240
  const qty = G.inventory[id]||0;
  if(qty <= 0){ notify('Nothing to sell','kill'); return; }
  const price = vendorPrice(id);
  G.gold = (G.gold||0) + price*qty;
  delete G.inventory[id];
  recordVendorSale(id, qty, price);   // b240: undoable
  notify(`Sold ${qty}× ${it.n} (+${(price*qty).toLocaleString()}🪙)`,'loot');
  updateTopbar(); renderInvNew(); closeInvDetail();
}
function invSellSelected(){
  if(!window._invSelected.size){ notify('Nothing selected','kill'); return; }
  let total = 0, count = 0, skipped = 0;
  for(const id of window._invSelected){
    const it = ITEMS[id]; if(!it) continue;
    if(isItemLocked(id)){ skipped++; continue; }   // b240: locked items are left alone
    const qty = G.inventory[id]||0; if(qty<=0) continue;
    const price = vendorPrice(id);
    total += price*qty; count += qty;
    delete G.inventory[id];
    recordVendorSale(id, qty, price);   // b240: undoable
  }
  G.gold = (G.gold||0) + total;
  window._invSelected.clear();
  notify(`Sold ${count} items for ${total.toLocaleString()}🪙` + (skipped?` · ${skipped} locked item(s) skipped`:''),'loot');
  window._invSelectMode = false;
  updateTopbar(); renderInvNew();
}

/* ══════════════════════════════════════════════════════════════════════
   b240 (Tyler) — SELL-LOCK + VENDOR BUY-BACK.
   Two safety nets around the vendor so an accidental tap never loses a thing:
   • Lock an item and it cannot be sold until you unlock it (a padlock in the
     flyout; every sell path checks isItemLocked first).
   • Every vendor sale is recorded; the last 15 are buyable BACK at the exact
     price you got, from the Buy-Back window — an undo for the vendor.
   Both live on G (saved), so they survive a reload. Vendor gold is client-side
   in this game (the market is the server-authoritative economy), so this needs
   no server round-trip and cannot mint value — you only ever buy back what you
   sold, at what you sold it for. ═══════════════════════════════════════════ */
function isItemLocked(id){ return !!(G.lockedItems && G.lockedItems[id]); }
function toggleItemLock(id){
  G.lockedItems = G.lockedItems || {};
  if(G.lockedItems[id]){ delete G.lockedItems[id]; notify('Unlocked — this item can be sold','info'); }
  else { G.lockedItems[id] = true; notify('Locked — protected from selling','info'); }
  try{ saveLocal(); }catch(e){}
  try{ if(typeof renderInvFancy==='function') renderInvFancy(); }catch(e){}
  try{ if(typeof renderInvNew==='function') renderInvNew(); }catch(e){}
  try{ if(typeof openInvDetail==='function' && window._invDetailId===id) openInvDetail(id); }catch(e){}
}
function recordVendorSale(id, qty, unit){
  if(!qty || unit==null) return;
  G.buyback = Array.isArray(G.buyback) ? G.buyback : [];
  const ex = G.buyback.find(b => b.id===id && b.unit===unit);
  if(ex){ ex.qty += qty; ex.at = Date.now(); }
  else { G.buyback.unshift({ id, qty, unit, at: Date.now() }); }
  if(G.buyback.length > 15) G.buyback.length = 15;
}
function repurchase(idx){
  G.buyback = Array.isArray(G.buyback) ? G.buyback : [];
  const b = G.buyback[idx]; if(!b) return;
  const it = ITEMS[b.id]; if(!it){ G.buyback.splice(idx,1); return; }
  const cost = b.unit * b.qty;
  if((G.gold||0) < cost){ notify('Not enough gold to buy it back','kill'); return; }
  G.gold -= cost;
  addItem(b.id, b.qty);
  G.buyback.splice(idx, 1);
  notify(`Bought back ${b.qty}× ${it.n} (−${cost.toLocaleString()}🪙)`,'loot');
  try{ saveLocal(); }catch(e){}
  updateTopbar();
  renderBuyback();
  try{ if(typeof renderInvFancy==='function') renderInvFancy(); }catch(e){}
}
window.isItemLocked = isItemLocked;
window.toggleItemLock = toggleItemLock;
window.recordVendorSale = recordVendorSale;
window.repurchase = repurchase;

function renderBuyback(){
  const body = document.getElementById('bb-modal-body');
  if(!body) return;
  const list = Array.isArray(G.buyback) ? G.buyback : [];
  if(!list.length){ body.innerHTML = '<div class="bb-empty">Nothing to buy back yet. Anything you sell to a vendor shows up here so you can undo it.</div>'; return; }
  body.innerHTML = list.map((b,i)=>{
    const it = ITEMS[b.id]; if(!it) return '';
    const cost = b.unit * b.qty;
    const afford = (G.gold||0) >= cost;
    const icon = (window._itemPath && window._itemPath[b.id]) ? `<img src="${window._itemPath[b.id]}" alt=""/>` : `<span class="bb-emoji">${it.icon||'❓'}</span>`;
    return `<div class="bb-row">
      <span class="bb-ic">${icon}</span>
      <span class="bb-meta"><b>${b.qty}× ${it.n}</b><span>sold for ${b.unit.toLocaleString()}🪙 each</span></span>
      <button class="btn btn-sm ${afford?'btn-primary':''}" ${afford?'':'disabled'} onclick="repurchase(${i})">Buy back · ${cost.toLocaleString()}🪙</button>
    </div>`;
  }).join('');
}
function openBuyback(){
  let m = document.getElementById('bb-modal');
  if(!m){
    m = document.createElement('div');
    m.id = 'bb-modal'; m.className = 'modal';
    m.innerHTML = '<div class="modal-card"><div class="modal-head"><div class="modal-title">Buy Back</div>'
      + '<button class="btn btn-sm" onclick="document.getElementById(\'bb-modal\').classList.remove(\'show\')">Close</button></div>'
      + '<div id="bb-modal-body" class="bb-body"></div></div>';
    document.body.appendChild(m);
  }
  renderBuyback();
  m.classList.add('show');
}
window.renderBuyback = renderBuyback;
window.openBuyback = openBuyback;

/* b265: ONE bury path. The three inventory bury buttons had DIVERGED — the
   context menu (inv-context-menu.js) and the inv detail (below) fell back to
   burying a SINGLE bone because window.buryBones was never defined, while the
   item-ux quantity slider buried the chosen qty. Tester: "sometimes it lets you
   bury them all, sometimes 1 by 1." A plain Bury now buries the WHOLE stack; the
   slider still passes an explicit qty. Returns the number buried. */
function buryBones(id, qty){
  const it = (typeof ITEMS !== 'undefined') && ITEMS[id];
  if(!it || !it.buryXp) return 0;
  const have = (G.inventory && G.inventory[id]) || 0;
  const n = (qty && qty > 0) ? Math.min(qty, have) : have;   // default: the whole stack
  if(n <= 0) return 0;
  removeItem(id, n);
  addXp('prayer', it.buryXp * n);
  G.stats = G.stats || {}; G.stats.buried = (G.stats.buried || 0) + n;
  notify('Buried ' + n + '× ' + it.n + ' (+' + Math.round(it.buryXp * n) + ' Prayer XP)', 'levelup');
  return n;
}
window.buryBones = buryBones;

/* ───── Render: equipment paper-doll + loadouts + bag w/ filters ───── */
function renderInvNew(){
  const eqEl = document.getElementById('equip-panel');
  const bagEl = document.getElementById('inv-panel');
  if(!eqEl || !bagEl) return;
  if(typeof migrateEquipmentSlots === 'function') migrateEquipmentSlots();

  const stats = _eqStatsTotals();
  const slotIcon = slot => (typeof EQUIP_SLOT_META !== 'undefined' && EQUIP_SLOT_META[slot]) ? EQUIP_SLOT_META[slot].icon : '▫️';
  const slotLabel = slot => (typeof EQUIP_SLOT_META !== 'undefined' && EQUIP_SLOT_META[slot]) ? EQUIP_SLOT_META[slot].label : slot;
  const slotBtn = (slot)=>{
    const id = G.equipment ? G.equipment[slot] : null;
    const it = id ? ITEMS[id] : null;
    const tier = it ? _itemTier(id) : 0;
    const svg = window._slotSVG && window._slotSVG[slot];
    if(!it){
      return `<button class="inv-slot empty" data-slot="${slot}" title="${slotLabel(slot)}"><span class="slot-svg">${svg||''}</span></button>`;
    }
    return `<button class="inv-slot" data-slot="${slot}" onclick="unequipSlotInv('${slot}')" title="${it.n} (tap to unequip)">${it.icon}${tier?`<span class="tier">T${tier}</span>`:''}${(it&&it.hands===2)?'<span class="twoH">2H</span>':''}</button>`;
  };

  /* Loadout pill bar */
  const loadoutsHtml = G.loadouts.map((l,i)=>{
    const isActive = window._activeLoadout === i;
    const summary = l.set
      ? `${Object.values(l.equipment||{}).filter(Boolean).length}+${Object.values(l.tools||{}).filter(Boolean).length} items`
      : 'empty';
    return `<button class="inv-loadout ${isActive?'active':''}" oncontextmenu="event.preventDefault();saveLoadout(${i});return false" onclick="${l.set?`applyLoadout(${i})`:`saveLoadout(${i})`}" title="${l.set?'Tap to apply · long-press / right-click to overwrite':'Tap to save current kit'}">
      <span class="ld-icon">${l.icon}</span>
      <span class="ld-name">${l.name}</span>
      <span class="ld-empty">${summary}</span>
      <span class="ld-actions">
        <span class="ld-act" onclick="event.stopPropagation();renameLoadout(${i})" title="Rename">✏️</span>
        ${l.set?`<span class="ld-act" onclick="event.stopPropagation();clearLoadout(${i})" title="Clear">✕</span>`:''}
      </span>
    </button>`;
  }).join('');

  /* Paper-doll: centered body avatar, slots arc around it via grid-template-areas */
  const SLOT_ORDER = ['helmet','earrings','necklace','cape','weapon','body','ammo','ring1','ring2','gloves','belt','boots','pants','companion'];
  const doll = `<div class="inv-doll">${SLOT_ORDER.map(s=>slotBtn(s)).join('')}</div>`;

  /* Held tools rail */
  let toolsRail = '';
  if(typeof TOOL_SLOTS !== 'undefined' && Array.isArray(TOOL_SLOTS) && G.tools){
    toolsRail = `<div class="inv-eq-title" style="margin:6px 0 4px">Tools</div>
      <div class="inv-tool-rail">${TOOL_SLOTS.map(t=>{
        const id = G.tools[t.slot];
        const it = id ? ITEMS[id] : null;
        const tier = it ? (it.tier || _itemTier(id)) : 0;
        return `<button class="inv-slot ${it?'':'empty'}" title="${it?it.n:t.label}">${it?it.icon:t.icon}<small>${it?_shortName(it.n):t.label}</small>${tier?`<span class="tier">T${tier}</span>`:''}</button>`;
      }).join('')}</div>`;
  }

  eqEl.innerHTML = `
    <div class="inv-eq-head">
      <div class="inv-eq-title">Loadout</div>
      <div class="inv-eq-stats"><span><b>+${stats.atk}</b> atk</span><span><b>+${stats.str}</b> str</span><span><b>+${stats.def}</b> def</span></div>
    </div>
    <div class="inv-loadouts">${loadoutsHtml}</div>
    ${doll}
    ${toolsRail}
    `;

  /* Bag side */
  const src = (typeof invTab !== 'undefined' && invTab === 'bank') ? G.bank : G.inventory;
  const items = _filteredItems(src);
  const totalCount = items.reduce((s,[id,q])=>s+q, 0);
  const totalValue = items.reduce((s,[id,q])=>s+vendorPrice(id)*q, 0);

  const filtersHtml = _CATEGORIES.map(c=>{
    const isAct = window._invFilter === c.id;
    return `<button class="inv-filter ${isAct?'active':''}" onclick="invSetFilter('${c.id}')">${c.label}</button>`;
  }).join('');

  // b140 (Batch E): toolbar gets a Sell-junk button next to Select. Hidden
  // when there's no junk (HearthriseInvCtx.selectJunk returns empty).
  // Threshold lives on G so the player can tweak it later.
  const junkThreshold = (G.junkThreshold|0) || 50;
  const junkPreview = (window.HearthriseInvCtx && window.HearthriseInvCtx.selectJunk)
    ? window.HearthriseInvCtx.selectJunk(junkThreshold)
    : [];
  const junkBtnHtml = junkPreview.length
    ? `<button class="inv-sell-junk" onclick="window.HearthriseInvCtx.sellJunk(${junkThreshold})" title="Sell every stack worth less than ${junkThreshold}g per item — never sells food, gear, or recipe scrolls">🧹 Sell junk (${junkPreview.length})</button>`
    : '';
  const toolbarHtml = `
    <div class="inv-toolbar">
      <div class="inv-search">
        <span style="font-size:calc(16px * var(--ui-scale, 1))">🔍</span>
        <input type="text" placeholder="Search…" value="${(window._invSearch||'').replace(/"/g,'&quot;')}" oninput="invSetSearch(this.value)">
      </div>
      <select class="inv-sort" onchange="invSetSort(this.value)">
        <option value="recent" ${window._invSort==='recent'?'selected':''}>Recent</option>
        <option value="name" ${window._invSort==='name'?'selected':''}>Name</option>
        <option value="value" ${window._invSort==='value'?'selected':''}>Value</option>
        <option value="qty" ${window._invSort==='qty'?'selected':''}>Quantity</option>
      </select>
      <button class="inv-select-toggle ${window._invSelectMode?'active':''}" onclick="invToggleSelectMode()">${window._invSelectMode?'✓ Selecting':'Select'}</button>
      ${junkBtnHtml}
    </div>
    <div class="inv-filters">${filtersHtml}</div>`;

  let gridHtml;
  if(!items.length){
    gridHtml = `<div class="inv-empty"><span class="em-icon">${(window._invSearch||window._invFilter!=='all')?'🔍':'🎒'}</span>${(window._invSearch||window._invFilter!=='all')?'Nothing matches your filters.':'Your bag is empty.'}</div>`;
  } else {
    gridHtml = `<div class="inv-grid ${window._invSelectMode?'inv-mode-select':''}">${items.map(([id,qty])=>{
      const it = ITEMS[id]; if(!it) return '';
      const cat = _itemCategory(it);
      const sel = window._invSelected.has(id);
      const tier = _itemTier(id);
      const qShow = qty>=10000?(qty/1000).toFixed(1)+'k':qty>=1000?(qty/1000).toFixed(1)+'k':qty;
      return `<button class="inv-item ${sel?'selected':''}" data-cat="${cat}" onclick="invItemTap('${id}')" title="${it.n} ×${qty} · ${vendorPrice(id)}🪙 each">
        <span class="selbox"></span>
        <span style="font-size:calc(25px * var(--ui-scale, 1));line-height:1">${it.icon}</span>
        <span class="qty">${qShow}</span>
        <span class="nm">${_shortName(it.n)}</span>
        ${tier?`<span class="tier">T${tier}</span>`:''}
      </button>`;
    }).join('')}</div>`;
  }

  let batchBar = '';
  if(window._invSelectMode){
    let selValue = 0, selCount = 0;
    for(const id of window._invSelected){
      const q = G.inventory[id]||0;
      selValue += vendorPrice(id)*q;
      selCount += q;
    }
    batchBar = `<div class="inv-batch-bar">
      <div class="bb-info"><b>${window._invSelected.size}</b> stacks · <b>${selCount.toLocaleString()}</b> items · worth <b>${selValue.toLocaleString()}🪙</b></div>
      <div class="bb-actions">
        <button class="btn" onclick="window._invSelected.clear();renderInvNew()">Clear</button>
        <button class="btn btn-danger" onclick="invSellSelected()">Sell Selected</button>
      </div>
    </div>`;
  }

  const summaryHtml = items.length ? `<div class="muted tiny" style="margin-top:8px;display:flex;justify-content:space-between"><span>${items.length} stack${items.length!==1?'s':''} · ${totalCount.toLocaleString()} items</span><span>worth ${totalValue.toLocaleString()}🪙</span></div>` : '';

  /* Tester report (paione): the bag re-renders every combat/skill tick, and
     replacing innerHTML resets the scroll container to the top — so browsing
     your bag mid-fight kept snapping you back up. Preserve the nearest
     scrollable ancestor's position across the swap. */
  const _scroller = _nearestScrollable(bagEl);
  const _savedTop = _scroller ? _scroller.scrollTop : 0;
  bagEl.innerHTML = toolbarHtml + gridHtml + summaryHtml + batchBar;
  if(_scroller) _scroller.scrollTop = _savedTop;
}

/* Nearest scrollable ancestor (incl. the element itself) — used to keep a
   panel's scroll position stable when its innerHTML is rebuilt in place. */
function _nearestScrollable(el){
  for(let n = el; n && n !== document.body && n !== document.documentElement; n = n.parentElement){
    const oy = getComputedStyle(n).overflowY;
    if((oy === 'auto' || oy === 'scroll') && n.scrollHeight > n.clientHeight + 2) return n;
  }
  return null;
}

function invSetFilter(id){ window._invFilter=id; renderInvNew(); }
function invSetSearch(v){ window._invSearch=v||''; renderInvNew(); }
function invSetSort(v){ window._invSort=v||'recent'; renderInvNew(); }
function invToggleSelectMode(){
  window._invSelectMode = !window._invSelectMode;
  if(!window._invSelectMode) window._invSelected.clear();
  renderInvNew();
}
function invItemTap(id){
  if(window._invSelectMode){
    if(window._invSelected.has(id)) window._invSelected.delete(id);
    else window._invSelected.add(id);
    renderInvNew();
    return;
  }
  openInvDetail(id);
}
