/* Patch the inventory item renderer to draw SVG when available.
   Only runs if window._itemSVG[id] exists; otherwise the item keeps its emoji. */
(function patchIconRender(){
  const _origRender = window.renderInvNew;
  if(typeof _origRender !== 'function') return;

  /* Override slotBtn to render SVG for known item ids */
  const _origInvNew = renderInvNew;
  /* We hook by patching the post-render DOM each pass: walk inv-item nodes and
     replace the inner icon span when a mapping exists. */
  function paintIcons(){
    document.querySelectorAll('.inv-item, .inv-slot:not(.empty)').forEach(node=>{
      const onclick = node.getAttribute('onclick') || '';
      const m = onclick.match(/(?:invItemTap|unequipSlotInv)\('([^']+)'/);
      if(!m) return;
      let id = m[1];
      /* For unequipSlotInv we got the slot, we need the item in that slot */
      if(onclick.includes('unequipSlotInv')){
        const slot = id;
        id = G.equipment ? G.equipment[slot] : null;
      }
      const svg = id && window._itemSVG && window._itemSVG[id];
      if(!svg) return;
      /* If the icon span already exists (from a previous pass) skip */
      if(node.querySelector('.item-svg')) return;
      /* Find the emoji-bearing first text node / span and replace */
      const emojiSpan = node.querySelector('span[style*="font-size:calc(25px * var(--ui-scale, 1))"]') || null;
      if(emojiSpan){
        emojiSpan.innerHTML = '<span class="item-svg">'+svg+'</span>';
      } else {
        /* equipped slot — first text child is the emoji */
        const first = node.firstChild;
        if(first && first.nodeType === Node.TEXT_NODE){
          const wrap = document.createElement('span');
          wrap.className = 'item-svg';
          wrap.innerHTML = svg;
          node.replaceChild(wrap, first);
        }
      }
    });
    /* Monster picker: replace icons for slime/goblin */
    document.querySelectorAll('.monster-row .mi').forEach(el=>{
      const txt = el.textContent.trim();
      const id = txt === '🟢' ? 'slime' : txt === '👺' ? 'goblin' : null;
      if(!id) return;
      const svg = window._itemSVG[id];
      if(svg && !el.querySelector('.item-svg')){
        el.innerHTML = '<span class="item-svg">'+svg+'</span>';
      }
    });
  }

  /* Wrap the new-style inventory renderer so we paint icons after each render */
  window.renderInvNew = function(){
    _origInvNew && _origInvNew.apply(this, arguments);
    setTimeout(paintIcons, 0);
  };

  /* Also paint after combat / monster list renders */
  const _origRenderMonsterList = window.renderMonsterList;
  if(typeof _origRenderMonsterList === 'function'){
    window.renderMonsterList = function(){
      _origRenderMonsterList.apply(this, arguments);
      setTimeout(paintIcons, 0);
    };
  }
  const _origRenderCombat = window.renderCombat;
  if(typeof _origRenderCombat === 'function'){
    window.renderCombat = function(){
      _origRenderCombat.apply(this, arguments);
      setTimeout(paintIcons, 0);
    };
  }

  /* Initial paint */
  setTimeout(paintIcons, 100);
  /* Keep painting on tab switches */
  document.addEventListener('click', e=>{
    const nav = e.target.closest && e.target.closest('[data-tab]');
    if(nav) setTimeout(paintIcons, 50);
  });

  console.log('Icon POC loaded:', Object.keys(window._itemSVG).length, 'items mapped');
})();

