"use strict";
/* ════════════════════════════════════════════════════════════
   PERSISTENT ACTIVITY BAR
   Slot below topbar. Shows current action + progress + stop.
   Reads from G.activeMonster / G.activeSkill / G.activeAction.
   Updates every 100ms via tick. No engine changes.
   ════════════════════════════════════════════════════════════ */

(function injectActivityBar(){
  if(document.getElementById('activity-bar')) return;
  const main = document.querySelector('.main'); if(!main) return;
  const topbar = main.querySelector('.topbar'); if(!topbar) return;
  const bar = document.createElement('div');
  bar.id = 'activity-bar';
  bar.className = 'activity-bar v2 idle';
  // Compact pill: icon + activity name + meta (Lv X · 12,345 xp/hr) + Stop.
  // No progress bar here — that lives inside the relevant activity panel.
  bar.innerHTML = `
    <div class="ab-icon" id="ab-icon"></div>
    <div class="ab-info">
      <div class="ab-name" id="ab-name">Idle — pick an activity</div>
    </div>
    <div class="ab-meta" id="ab-meta"></div>
    <button class="ab-stop" id="ab-stop">Stop</button>`;
  /* insert right after topbar */
  topbar.insertAdjacentElement('afterend', bar);
  bar.querySelector('#ab-stop').addEventListener('click', stopCurrentActivity);
})();

/* b217: the activity bar's icon slot took a raw emoji (💤 when idle, the
 * monster's or skill's emoji when busy) and sits under the topbar on every
 * screen — the single most-seen pictograph in the build. This paints a gilt
 * glyph instead, falling back to nothing rather than to an emoji. */
function setActivityIcon(el, glyphKey, color){
  if(!el) return;
  var g = (window.HR && window.HR.icon) ? window.HR.icon(glyphKey, 18, color || 'currentColor') : null;
  el.innerHTML = g || '';
}
function stopCurrentActivity(){
  if(G.activeMonster && typeof stopCombat === 'function'){ stopCombat(); return; }
  if(G.activeSkill && typeof stopSkill === 'function'){ stopSkill(); return; }
  if(G.activeAction && typeof stopAction === 'function'){ stopAction(); return; }
}

/* Compute progress fraction. We try several common paths since this game
   has multiple action loops (combat tick + gather skill tick). */
function _activityProgress(){
  if(G.activeMonster){
    /* Monster combat: tick is fixed (~2.4s). We can fake fluid progress
       by interpolating between combatLog entries — but cleaner: read
       G._combatTickStart if set, else just animate via timer. */
    const tickMs = (typeof COMBAT_BALANCE === 'object' && COMBAT_BALANCE.tickMs) || 2400;
    const last = G._combatTickStart || (G._combatTickStart = Date.now());
    const elapsed = Date.now() - last;
    return Math.min(1, elapsed / tickMs);
  }
  if(G.activeSkill && typeof G.skillProgress === 'number'){
    return Math.min(1, G.skillProgress || 0);
  }
  if(G.activeAction && typeof G.actionProgress === 'number'){
    return Math.min(1, G.actionProgress || 0);
  }
  return 0;
}

function _activityXpHr(){
  /* Estimate XP/hr for current skill action */
  if(G.activeSkill && G.skillTargetId){
    let t = null;
    if(G.activeSkill === 'woodcutting' && typeof TREES !== 'undefined') t = TREES.find(a=>a.id===G.skillTargetId);
    else if(G.activeSkill === 'mining' && typeof ROCKS !== 'undefined') t = ROCKS.find(a=>a.id===G.skillTargetId);
    else if(G.activeSkill === 'fishing' && typeof FISH_SPOTS !== 'undefined') t = FISH_SPOTS.find(a=>a.id===G.skillTargetId);
    /* b226: through actionRate(), so the pill quotes the rate the engine
       actually pays — pace, tools, perks and presence included. */
    if(t){ const r = actionRate(G.activeSkill, t); return r ? r.xpPerHour : null; }
  }
  return null;
}
/* b326 — the AWAY rate for the same action, computed with `away:true`
   (away-time-ruling.md, honesty item 5). Returned only when it genuinely
   differs from the live rate, because a second identical number beside the
   first is noise, and this pill lives in a 339px-tall landscape topbar.
   It differs exactly when a blessing or a food buff is lifting THIS activity
   — which is the moment the player most needs to know the night pays the
   base rate, and the moment they are most likely to assume otherwise. */
let _awayRateMemo = {k:null, v:null};
function _activityAwayXpHr(live){
  if(!(live > 0)) return null;
  if(!(G.activeSkill && G.skillTargetId)) return null;
  /* This bar refreshes at 10Hz and `actionRate` walks the seven-deep getBonus
     chain. Memoised on the LIVE rate, which is sound rather than merely cheap:
     the away stack is a strict subset of the live one, so nothing can move the
     away number without also moving the live number. */
  const memoKey = G.activeSkill + '|' + G.skillTargetId + '|' + live;
  if(_awayRateMemo.k === memoKey) return _awayRateMemo.v;
  let t = null;
  if(G.activeSkill === 'woodcutting' && typeof TREES !== 'undefined') t = TREES.find(a=>a.id===G.skillTargetId);
  else if(G.activeSkill === 'mining' && typeof ROCKS !== 'undefined') t = ROCKS.find(a=>a.id===G.skillTargetId);
  else if(G.activeSkill === 'fishing' && typeof FISH_SPOTS !== 'undefined') t = FISH_SPOTS.find(a=>a.id===G.skillTargetId);
  if(!t){ _awayRateMemo = {k:memoKey, v:null}; return null; }
  const r = actionRate(G.activeSkill, t, {away:true});
  const away = r ? r.xpPerHour : null;
  const out = (away && away !== live) ? away : null;
  _awayRateMemo = {k:memoKey, v:out};
  return out;
}

function refreshActivityBar(){
  const bar = document.getElementById('activity-bar'); if(!bar) return;
  const iconEl = document.getElementById('ab-icon');
  const nameEl = document.getElementById('ab-name');
  const metaEl = document.getElementById('ab-meta');
  const stopBtn = document.getElementById('ab-stop');

  /* Combat */
  if(G.activeMonster){
    const m = MONSTERS[G.activeMonster];
    bar.classList.remove('idle'); bar.classList.add('combat');
    setActivityIcon(iconEl, 'navCombat', 'var(--red)');
    if(nameEl) nameEl.textContent = `Fighting ${m?.name||'?'}`;
    if(metaEl){
      // Show kill count for the current foe (resets when the player picks a
      // new monster) + total session kills. The arena vs panel already shows
      // player HP, so the activity bar carries the more interesting numbers.
      const kills = (G.combatKillsThisFoe||0);
      const totalKills = (G.stats?.kills||0);
      /* b262 (paione): the bounty task progress lived in a card that fell below
         the fold of the short landscape combat view, so "how many kills left for
         my task" wasn't visible. Surface it in the always-on activity bar when
         the active bounty targets the monster you're fighting. */
      let bountyChip = '';
      const _ab = G.bountyHunter && G.bountyHunter.active;
      if(_ab && _ab.target === G.activeMonster){
        const _cur = _ab.type==='proof'
          ? Math.min((typeof bountyProofHave==='function'?bountyProofHave(_ab):0), _ab.required)
          : (_ab.progress||0);
        bountyChip = '<span class="ab-bounty">Bounty <b>'+_cur+'/'+_ab.required+'</b></span>';
      }
      /* b266 (tester): show the combat SKILL you're training + XP to the next
         level, right in the always-visible bar — "can I see Strength XP til level
         up while fighting?". Primary trained skill = the active style's highest-
         weighted skill. */
      let xpChip = '';
      const _st = (typeof window.getActiveCombatStyle==='function') ? window.getActiveCombatStyle() : null;
      if(_st && _st.xp){
        const _sk = Object.keys(_st.xp).sort((a,b)=>_st.xp[b]-_st.xp[a])[0];
        if(_sk){
          const _xp = (G.skills && G.skills[_sk]) || 0;
          const _lv = levelFromXp(_xp), _to = xpToNext(_xp);
          const _lbl = _sk.slice(0,3).toUpperCase();
          xpChip = _lv>=99
            ? '<span class="ab-xp">'+_lbl+' <b>99</b></span>'
            : '<span class="ab-xp">'+_lbl+' <b>'+_lv+'</b> · '+_to.toLocaleString()+' to go</span>';
        }
      }
      /* ── b342: THE COMBAT SCREEN HAS TO SAY "LICENCE" ─────────────────────
         docs/design/away-combat-licence.md §4.2: "the counter has to exist
         before the goal does". It did not exist anywhere a fighting player
         looks — the word appeared on ZERO panels — while the two boss cards at
         the top of this same screen promised "Pays while you're away" twice.

         This bar is the cheapest place in the game to fix that: it is the one
         readout that is on screen for every second of every fight, and it was
         already printing a lifetime kill total that is the SAME NUMBER the
         licence gates on. So before the licence, the total re-labels itself as
         the counter (41 / 100), and after it, it goes back to Lifetime and
         says the thing the counter was earning. No new number, no new query,
         no new panel real estate — one chip that changes what it means when
         the player's situation changes.

         `check()` is the same predicate src/core/licence.js gives the away
         path, so the bar and the gate can never disagree. Missing module →
         no chip, never a wrong chip. */
      let licChip = '', awayChip = '';
      const _lic = (window.HearthriseLicence && typeof window.HearthriseLicence.check==='function')
        ? window.HearthriseLicence.check(G) : null;
      if(_lic && !_lic.ok){
        licChip = '<span class="ab-tkills" title="Land '+_lic.need+' kills by hand to earn your Field '
          +'Licence. Until then a fight only pays while you are here — skills pay in full either way.">'
          +'Field Licence <b>'+_lic.kills.toLocaleString()+'</b> / '+_lic.need.toLocaleString()+'</span>';
        awayChip = '<span class="ab-xph ab-away" title="Combat does not pay while you are away until the '
          +'Field Licence is earned.">no away pay yet</span>';
      } else {
        licChip = '<span class="ab-tkills">Lifetime <b>'+totalKills.toLocaleString()+'</b></span>';
        if(_lic) awayChip = '<span class="ab-xph ab-away" title="Your Field Licence is earned — this fight '
          +'carries on while you are away, at the base rate.">pays away</span>';
      }
      metaEl.innerHTML = ''
        + '<span class="ab-kills">⚔️ <b>'+kills.toLocaleString()+'</b> this fight</span>'
        + xpChip
        + bountyChip
        + licChip
        + awayChip;
    }
    if(stopBtn) stopBtn.style.display = '';
    refreshPanelProgress();
    return;
  }
  /* Skill training */
  if(G.activeSkill){
    const s = SKILLS_DEF[G.activeSkill];
    bar.classList.remove('idle','combat');
    setActivityIcon(iconEl, G.activeSkill, 'var(--green)');
    let actName = G.skillTargetId ? G.skillTargetId.replace(/_/g,' ') : '';
    if(nameEl) nameEl.textContent = `${s?.name||G.activeSkill}${actName?' — '+actName:''}`;
    const xph = _activityXpHr();
    if(metaEl){
      const lv = (typeof getLevel==='function') ? getLevel(G.activeSkill) : 0;
      /* b326: when a blessing or buff is lifting this activity, state the rate
         an ABSENCE would pay right beside it. Same calculator, `away:true`. */
      const awayXph = _activityAwayXpHr(xph);
      metaEl.innerHTML = `<span class="ab-lv">Lv <b>${lv}</b></span>${xph?`<span class="ab-xph"><b>${xph.toLocaleString()}</b> xp/hr</span>`:''}`
        + (awayXph?`<span class="ab-xph ab-away" title="Blessings and food buffs pay while you play. An absence is paid at the base rate."><b>${awayXph.toLocaleString()}</b> away</span>`:'');
    }
    if(stopBtn) stopBtn.style.display = '';
    refreshPanelProgress();
    return;
  }
  /* Generic action loop (smelt/saw/forge/cook in some branches) */
  if(G.activeAction){
    const a = G.activeAction;
    const map = {smelt:'uiFire',saw:'uiAxe',forge:'uiAnvil',cook:'cooking',craft:'crafting',enchant:'uiSpark',pray:'prayer'};
    const labelMap = {smelt:'Smelting',saw:'Sawing',forge:'Forging',cook:'Cooking',craft:'Crafting',enchant:'Enchanting',pray:'Bury'};
    bar.classList.remove('idle','combat');
    setActivityIcon(iconEl, map[a.kind] || 'uiAnvil', 'var(--gold-2)');
    if(nameEl) nameEl.textContent = `${labelMap[a.kind]||a.kind} — ${(a.targetId||'').replace(/_/g,' ')}`;
    if(metaEl) metaEl.innerHTML = '';
    if(stopBtn) stopBtn.style.display = '';
    refreshPanelProgress();
    return;
  }
  /* Artisan (cooking/smithing/crafting recipes) — Phase A.1 onwards uses
     this path instead of legacy activeAction. */
  if(G.activeArtisanRecipe){
    const map = {cooking:'cooking', smithing:'smithing', crafting:'crafting', prayer:'prayer'};
    const skill = G.activeArtisanSkill || 'cooking';
    bar.classList.remove('idle','combat');
    setActivityIcon(iconEl, map[skill] || 'uiAnvil', 'var(--gold-2)');
    if(nameEl){
      const recipeName = G.activeArtisanRecipe.replace(/^[a-z]+_/,'').replace(/_/g,' ');
      nameEl.textContent = `${skill[0].toUpperCase()}${skill.slice(1)} — ${recipeName}`;
    }
    if(metaEl){
      const lv = (typeof getLevel==='function') ? getLevel(skill) : 0;
      metaEl.innerHTML = `<span class="ab-lv">Lv <b>${lv}</b></span>`;
    }
    if(stopBtn) stopBtn.style.display = '';
    refreshPanelProgress();
    return;
  }
  /* Idle */
  bar.classList.add('idle'); bar.classList.remove('combat');
  setActivityIcon(iconEl, 'uiIdle', 'var(--ink-3)');
  if(nameEl) nameEl.textContent = 'Idle — pick an activity';
  if(metaEl) metaEl.innerHTML = '';
  if(stopBtn) stopBtn.style.display = 'none';

  // Drive the per-tab progress bar (only visible when the active tab
  // matches the kind of activity in progress).
  refreshPanelProgress();
}

// ── Per-tab progress bar ─────────────────────────────────────────
// A separate <div class="panel-progress"> is appended to each panel
// that hosts an activity. It auto-shows/hides + tracks progress.
function ensurePanelProgress(panelId){
  const panel = document.getElementById(panelId);
  if(!panel) return null;
  let pp = panel.querySelector(':scope > .panel-progress');
  if(!pp){
    pp = document.createElement('div');
    pp.className = 'panel-progress';
    pp.innerHTML = `
      <div class="pp-row">
        <span class="pp-label" data-pp="label">—</span>
        <span class="pp-meta" data-pp="meta"></span>
      </div>
      <div class="pp-bar"><i data-pp="fill" style="width:0%"></i></div>`;
    // Insert at the very top of the panel so it sits above other cards.
    panel.insertBefore(pp, panel.firstChild);
  }
  return pp;
}

function refreshPanelProgress(){
  // Possible activity panels: combat, skills (per-skill), artisan-skills.
  const activeTab = document.querySelector('.panel.active')?.id || '';
  const updateOne = function(panelId, label, meta, pct, kind){
    const pp = ensurePanelProgress(panelId); if(!pp) return;
    const visible = activeTab === panelId;
    pp.style.display = visible ? '' : 'none';
    if(!visible) return;
    pp.dataset.kind = kind || '';
    const lbl = pp.querySelector('[data-pp=label]');
    const mta = pp.querySelector('[data-pp=meta]');
    const fill = pp.querySelector('[data-pp=fill]');
    if(lbl) lbl.textContent = label;
    if(mta) mta.textContent = meta || '';
    if(fill) fill.style.width = (Math.max(0,Math.min(1,pct))*100).toFixed(1)+'%';
  };

  // Hide all first; the matching one will be shown.
  document.querySelectorAll('.panel-progress').forEach(p => { p.style.display = 'none'; });

  if(G.activeMonster){
    // Combat has its own arena-vs panel + activity bar HP — suppress the
    // small panel-progress strip on the combat tab to avoid redundancy.
    return;
  }
  if(G.activeSkill){
    const s = SKILLS_DEF[G.activeSkill] || {};
    const target = G.skillTargetId ? G.skillTargetId.replace(/_/g,' ') : '';
    const xph = _activityXpHr();
    /* b229: Skills folded into the Character screen, so the per-tab progress
       strip lives on #panel-character now (it was keyed to #panel-skills, which
       is never the active panel any more — the strip would silently vanish). */
    updateOne('panel-character',
      `${s.name || G.activeSkill}${target?' — '+target:''}`,
      xph ? `${xph.toLocaleString()} xp/hr` : '',
      _activityProgress(),
      'skill');
    return;
  }
  if(G.activeArtisanRecipe){
    const skill = G.activeArtisanSkill || 'cooking';
    const recipeName = G.activeArtisanRecipe.replace(/^[a-z]+_/,'').replace(/_/g,' ');
    updateOne('panel-character',
      `${skill[0].toUpperCase()}${skill.slice(1)} — ${recipeName}`,
      '',
      Math.min(1, G.skillProgress || G.actionProgress || 0),
      'artisan');
    return;
  }
}

/* Reset combat tick timer when a tick fires so the progress animation matches reality */
const _origCombatTickAB = window.combatTick;
if(typeof _origCombatTickAB === 'function'){
  window.combatTick = function(){
    G._combatTickStart = Date.now();
    return _origCombatTickAB.apply(this, arguments);
  };
}
const _origStopCombatAB = window.stopCombat;
if(typeof _origStopCombatAB === 'function'){
  window.stopCombat = function(){ const r = _origStopCombatAB.apply(this, arguments); refreshActivityBar(); return r; };
}
const _origStartCombatAB = window.startCombat;
if(typeof _origStartCombatAB === 'function'){
  window.startCombat = function(){ G._combatTickStart = Date.now(); const r = _origStartCombatAB.apply(this, arguments); refreshActivityBar(); return r; };
}

/* Drive the bar at 10fps — and bank Time Played off the same tick (b229), so
   the counter rides an existing loop rather than adding a wall-clock of its own. */
setInterval(function(){ refreshActivityBar(); try{ tickPlayMs(); }catch(e){} }, 100);

console.log('Activity bar: loaded');

// ── Combat-mode arena VS visualization ─────────────────────────
// Toggles body.in-combat and injects a centered "PLAYER vs FOE" portrait
// + HP bars panel into #panel-combat .combat-arena when a fight is active.
(function setupArenaVs(){
  function ensureArenaVs(){
    var arena = document.querySelector('#panel-combat .combat-arena');
    if(!arena) return null;
    var vs = arena.querySelector(':scope > .arena-vs');
    if(!vs){
      vs = document.createElement('div');
      vs.className = 'arena-vs';
      /* b227: each fighter now carries an action slot directly under their own
         HP readout. They are MOUNTS, not markup — everything inside them is
         painted by HearthriseCombatHud (src/features/combat-render.js), which
         is where the new combat UI lives. The stage owns the geometry; the
         render module owns the contents. */
      vs.innerHTML = `
        <div class="arena-side player">
          <div class="arena-portrait" id="arena-player-portrait">🧙</div>
          <div class="arena-name" id="arena-player-name">You</div>
          <div class="arena-hp-bar"><i id="arena-player-hp" style="width:100%"></i></div>
          <div class="arena-hp-text" id="arena-player-hp-text">10 / 10</div>
          <div class="arena-act arena-act-player" id="arena-act-player"></div>
        </div>
        <div class="arena-vs-divider">VS</div>
        <div class="arena-side foe">
          <div class="arena-portrait" id="arena-foe-portrait">👾</div>
          <div class="arena-name" id="arena-foe-name">—</div>
          <div class="arena-hp-bar"><i id="arena-foe-hp" style="width:100%"></i></div>
          <div class="arena-hp-text" id="arena-foe-hp-text">— / —</div>
          <div class="arena-act arena-act-foe" id="arena-act-foe"></div>
        </div>`;
      // Insert before the card-body so it sits at the top of the arena.
      var head = arena.querySelector('.card-head');
      if(head && head.nextSibling){ arena.insertBefore(vs, head.nextSibling); }
      else { arena.appendChild(vs); }
    }
    return vs;
  }

  function refreshArenaVs(){
    var inCombat = !!(window.G && window.G.activeMonster);
    document.body.classList.toggle('in-combat', inCombat);
    var existing = document.querySelector('#panel-combat .combat-arena > .arena-vs');
    if(!inCombat){
      // Hide the arena-vs panel when not fighting so stale player/foe
      // portraits don't linger.
      if(existing) existing.style.display = 'none';
      if(window.HearthriseCombatHud) window.HearthriseCombatHud.refresh();
      return;
    }
    ensureArenaVs();
    if(existing) existing.style.display = '';
    var m = window.MONSTERS && window.MONSTERS[window.G.activeMonster];
    var foeIcon = (window._monsterIcon && window._monsterIcon[window.G.activeMonster])
      ? '<img src="'+window._monsterIcon[window.G.activeMonster]+'" alt="">'
      : (m?.icon || '👾');
    var pf = document.getElementById('arena-foe-portrait');
    var pn = document.getElementById('arena-foe-name');
    var phb = document.getElementById('arena-foe-hp');
    var pht = document.getElementById('arena-foe-hp-text');
    /* b297: only rewrite the foe icon when it actually changes. This tick runs
       every 200ms; blindly setting innerHTML wiped any floating damage number
       or DEFEATED stamp appended to the portrait within 200ms — the death FX
       had nothing to render into. Keyed on monster + icon string so a late
       icon-load still swaps in, while a respawn of the same foe leaves the
       overlay children alone. */
    if(pf){
      var wantFoe = window.G.activeMonster + '|' + foeIcon;
      if(pf.getAttribute('data-foe') !== wantFoe){ pf.innerHTML = foeIcon; pf.setAttribute('data-foe', wantFoe); }
    }
    if(pn) pn.textContent = m?.name || window.G.activeMonster;
    var foePct = window.G.monsterMaxHp ? Math.max(0, (window.G.monsterHp/window.G.monsterMaxHp)*100) : 0;
    if(phb) phb.style.width = foePct.toFixed(1)+'%';
    if(pht) pht.textContent = (window.G.monsterHp||0)+' / '+(window.G.monsterMaxHp||0);

    var pp = document.getElementById('arena-player-portrait');
    // b186: painted player portrait (set once so damage-number children survive)
    if(pp && !pp.querySelector('img')){
      pp.innerHTML = '<img src="'+(window._playerAvatar||'assets/icons-bundle/painted/npc/player.png')+'" alt="">';
    }
    var pnp = document.getElementById('arena-player-name');
    var php = document.getElementById('arena-player-hp');
    var phpt = document.getElementById('arena-player-hp-text');
    if(pnp) pnp.textContent = window.G.playerName || 'You';
    var pPct = window.G.playerMaxHp ? Math.max(0, (window.G.playerHp/window.G.playerMaxHp)*100) : 0;
    if(php) php.style.width = pPct.toFixed(1)+'%';
    if(phpt) phpt.textContent = (window.G.playerHp||0)+' / '+(window.G.playerMaxHp||0);
    /* b278 (Tyler: "I don't see my pet in the combat UI"): perch the equipped
       companion beside the hero in the arena, so it reads as fighting alongside
       you. Lives inside the player portrait (position:relative, overflow:visible).
       Painted icon only; hidden when no pet is equipped. The data-pet guard makes
       the 200ms refresh a no-op once drawn. */
    if(pp){
      var petHost = document.getElementById('arena-player-pet');
      if(!petHost){ petHost = document.createElement('div'); petHost.id='arena-player-pet'; petHost.className='arena-pet'; pp.appendChild(petHost); }
      var petId = (window.G.companions && window.G.companions.equipped) || null;
      if(petId && window.COMPANIONS && window.COMPANIONS[petId] && typeof window.companionIconHtml==='function'){
        var wantPet = 'pet:'+petId;
        if(petHost.getAttribute('data-pet')!==wantPet){
          petHost.innerHTML = window.companionIconHtml(petId, 30);
          petHost.setAttribute('data-pet', wantPet);
          petHost.title = (window.COMPANIONS[petId].n||'Companion') + ' — fighting with you';
        }
        petHost.style.display = '';
      } else if(petHost) { petHost.style.display = 'none'; }
    }

    /* b227: the two action slots ride the same 200ms tick as the HP bars, so
       "Eat · +8 HP · 12 left" can never disagree with the HP number printed
       directly above it. The HUD diffs before it repaints — see combat-render. */
    if(window.HearthriseCombatHud) window.HearthriseCombatHud.refresh();
  }

  /* b227: the stage's build step is published so the render module can paint
     into it on demand instead of waiting up to 200ms for the next tick. */
  window.HearthriseArenaStage = { ensure: ensureArenaVs, refresh: refreshArenaVs };

  // Tick alongside the activity bar
  setInterval(refreshArenaVs, 200);
  console.log('Arena VS: loaded');

  // Hook combatTick to also pop damage numbers on the new arena-vs portraits
  // (the original .fighter elements live inside .arena which we hid).
  var _lastP = null, _lastM = null;
  function popDmg(target, value, opts){
    if(!target) return;
    var num = document.createElement('div');
    num.className = 'dmg-num-vs' + (opts && opts.kill ? ' kill' : '') + (opts && opts.crit ? ' crit' : '') + (opts && opts.miss ? ' miss' : '');
    num.textContent = (opts && opts.miss) ? 'miss' : (value > 0 ? '-' + value : '0');
    target.appendChild(num);
    if(!opts || !opts.miss){
      target.classList.add('hit-shake');
      setTimeout(function(){ target.classList.remove('hit-shake'); }, 320);
    }
    setTimeout(function(){ num.remove(); }, 1100);
  }
  /* b297: the death throe. killMonster() has already respawned the foe to full
     HP by the time we get here, so we can't read the killing damage off the HP
     diff — pass in the HP the foe had before the fatal swing (a faithful stand-in
     for the killing hit). Shows that number big, stamps DEFEATED, and plays the
     collapse animation on the portrait, which the icon-guard now lets survive. */
  function deathFx(target, killDmg){
    if(!target) return;
    popDmg(target, killDmg > 0 ? killDmg : 1, { kill: true, crit: !!(window.G && window.G._lastPlayerCrit) });
    var tag = document.createElement('div');
    tag.className = 'defeat-tag';
    tag.textContent = 'Defeated';
    target.appendChild(tag);
    setTimeout(function(){ if(tag.parentNode) tag.parentNode.removeChild(tag); }, 1300);
    target.classList.add('foe-dying');
    setTimeout(function(){ target.classList.remove('foe-dying'); }, 760);
  }
  var _origTick = window.combatTick;
  if(typeof _origTick === 'function'){
    window.combatTick = function(){
      var beforeP = window.G && window.G.playerHp;
      var beforeM = window.G && window.G.monsterHp;
      var beforeKills = (window.G && window.G.stats && window.G.stats.kills) || 0;
      var r = _origTick.apply(this, arguments);
      var afterP = window.G && window.G.playerHp;
      var afterM = window.G && window.G.monsterHp;
      var afterKills = (window.G && window.G.stats && window.G.stats.kills) || 0;
      var foeP = document.querySelector('#panel-combat .arena-vs .arena-side.foe .arena-portrait');
      var youP = document.querySelector('#panel-combat .arena-vs .arena-side.player .arena-portrait');
      if(afterKills > beforeKills){
        /* A foe died this tick. beforeM is the HP it had before the fatal blow. */
        deathFx(foeP, beforeM != null ? beforeM : 0);
      } else if(beforeM != null && afterM < beforeM){
        popDmg(foeP, beforeM - afterM, { crit: !!(window.G && window.G._lastPlayerCrit) });
      } else if(beforeM != null && afterM === beforeM && window.G && window.G.activeMonster){
        var last = window.G.combatLog && window.G.combatLog[window.G.combatLog.length-1] || '';
        if(/miss/i.test(last) && /You/i.test(last)){
          popDmg(foeP, 0, { miss: true });
        }
      }
      if(beforeP != null && afterP < beforeP){
        popDmg(youP, beforeP - afterP, {});
      }
      _lastP = afterP; _lastM = afterM;
      return r;
    };
  }
})();

// ═════════════════════════════════════════════════════════════
// Combat preview modal — clicking a monster opens this panel with
// estimated DPS, drop table, your stats + Fight button. No more
// auto-starting combat. Inspired by Idle Clans-style combat preview.
// ═════════════════════════════════════════════════════════════
(function setupCombatPreview(){
  function ensureModal(){
    if(document.getElementById('mob-preview')) return;
    var ov = document.createElement('div');
    ov.id = 'mob-preview';
    ov.className = 'mob-preview-overlay';
    ov.innerHTML = '<div class="mp-modal" id="mp-modal"></div>';
    ov.addEventListener('click', function(e){ if(e.target === ov) closePreview(); });
    document.body.appendChild(ov);
  }
  function closePreview(){
    var ov = document.getElementById('mob-preview');
    if(ov) ov.classList.remove('open');
  }
  window.closeMobPreview = closePreview;

  function fmtNum(n){ return Math.round(n).toLocaleString(); }

  // Estimate damage range + hit chance + DPS using same math the engine
  // uses (best-effort — fallback to coarse approximation if engine helpers
  // aren't exposed).
  function estimateCombat(m){
    /* Wave 1 (audit fix): the preview MUST use the same engine the fight uses,
       or every number it shows before a fight is fiction. Route through
       getPlayerCombatRolls (the real accuracy/maxHit/crit) and combatTickMs (the
       real attack speed) instead of a second, divergent formula. Damage per swing
       is the expectation of the engine's swing — src/core/combat.js `rollAttack`,
       i.e. `chance(accuracy) ? int(1,maxHit) : 0` — with the 1.5× crit factored
       in at its rolled chance. */
    var eq = (typeof getEquipmentStats === 'function') ? getEquipmentStats() : {};
    var pr = (typeof getPlayerCombatRolls === 'function') ? getPlayerCombatRolls(m, eq) : null;
    var CB = (typeof window.COMBAT_BALANCE === 'object') ? window.COMBAT_BALANCE : {tickMs:2400, critMult:1.5};
    var maxHit, accuracy, critChance, weaknessBonus;
    if(pr){
      maxHit = pr.maxHit; accuracy = pr.accuracy; critChance = pr.critChance || 0;
      weaknessBonus = (pr.weak && pr.weak.matched) ? (WEAKNESS_BONUS ? WEAKNESS_BONUS.damage : 1.2) : 1.0;
    } else {
      // Defensive fallback only if the engine helper is somehow unavailable.
      var strLv = (typeof getLevel === 'function') ? getLevel('strength') : 1;
      maxHit = Math.max(1, Math.floor(strLv*0.35 + 2)); accuracy = 0.75; critChance = 0; weaknessBonus = 1.0;
    }
    var minHit = 1;                                   // engine rolls rand(1, maxHit)
    var meanHit = (1 + maxHit) / 2;                   // uniform mean
    var critMult = CB.critMult || 1.5;
    var avgDmg = accuracy * meanHit * (1 + critChance * (critMult - 1));
    var tickMs = (typeof combatTickMs === 'function') ? combatTickMs() : (CB.tickMs || 2400);
    var dps = avgDmg * (1000 / tickMs);
    var killTimeS = m.hp / Math.max(0.01, dps);
    var killsHr = 3600 / killTimeS;
    var xpHr = killsHr * (m.xp || 0);
    var goldHr = killsHr * (((m.gp && m.gp[0])||0) + ((m.gp && m.gp[1])||0))/2;
    var surv = estimateSurvival(m, killTimeS, tickMs);
    return {
      minHit: minHit, maxHit: maxHit,
      hitChance: accuracy, critChance: critChance,
      dps: dps, killTimeS: killTimeS,
      killsHr: killsHr, xpHr: xpHr, goldHr: goldHr,
      weaknessBonus: weaknessBonus,
      incomingDps: surv.incomingDps,
      effectiveHp: surv.effectiveHp,
      survivalKills: surv.survivalKills,
      survivalSeconds: surv.survivalSeconds,
      survivesAnHour: surv.survivalSeconds >= 3600,
      runXp: surv.survivalKills * (m.xp || 0),
      runGold: surv.survivalKills * (((m.gp && m.gp[0])||0) + ((m.gp && m.gp[1])||0))/2,
    };
  }

  /* ═══════════════════════════════════════════════════════════════════════
     b341 — THE MISSING HALF OF THE FORECAST (docs/design/away-combat-licence.md §4.1).

     estimateCombat() modelled OUTGOING damage only. It had no term for being
     hit — none, anywhere — which is how the preview came to advertise
     "KILLS/HR 340 · XP/HR 1,698" to a fresh character who is dead in under a
     minute. A forecast is a promise, and that one was off by two orders of
     magnitude on the axis that decides whether the player leaves the tab.

     THE RULE, and it is the load-bearing sentence:
       **A rate may only be quoted over a span the character can survive.**

     The model, and every term is derived rather than tuned:

       incomingPerSwing = foe.accuracy x (1 + foe.maxHit)/2      uniform 1..maxHit
       swingsPerKill    = killTimeS / swingS
       retaliations     = swingsPerKill - 1
         ── THE TERM THE SPEC'S DRAFT FORMULA OMITTED. simulateTick RETURNS on
            a kill, before the monster's swing (src/core/combat-sim.js: the
            `if (state.monsterHp <= 0)` branch is above `ctx.monsterRolls`), so
            the killing blow draws no reply. On an 8 HP Slime that is one swing
            in 4.4 — a 23% overstatement of incoming damage if you skip it, and
            it is exactly what put the draft outside its own acceptance window.
       incomingDps      = incomingPerSwing x (retaliations/swingsPerKill) / swingS
       effectiveHp      = playerHp + (auto-eat AND a slotted food ? qty x heals : 0)
         ── auto-actions.js:219 returns false without `traits.auto_eat`, so a
            character who does not own the trait eats NOTHING while away, no
            matter how much food is in the bag. Counting unslotted or
            unreachable food here would rebuild the original lie.
       survivalSeconds  = effectiveHp / incomingDps
       survivalKills    = floor(survivalSeconds / killTimeS)

     ACCEPTANCE (the spec's, so nobody has to trust these constants): a fresh
     save (10 HP, bronze sword, empty food slot) against Slime must land within
     5 kills +/-1 and 75s +/-20s. This model returns 5 kills / 61.3s.
     Ground truth from 4,000 seeded runs of the REAL engine: 4.49 kills /
     58.5s. Guarded by LICENCE-7.

     GATHERING PREVIEWS ARE NOT TOUCHED and must not be. `legacy.js:4062` and
     `:8663` quote an hourly rate for an activity that genuinely sustains it
     for eight hours, because a tree does not hit back. Harmonising the two
     would delete information from the honest one.
     ═══════════════════════════════════════════════════════════════════════ */
  function estimateSurvival(m, killTimeS, tickMs){
    var swingS = Math.max(0.001, tickMs / 1000);
    var eq = (typeof getEquipmentStats === 'function') ? getEquipmentStats() : {};
    var mr = (typeof getMonsterCombatRolls === 'function') ? getMonsterCombatRolls(m, eq) : null;
    var foeAcc = mr ? mr.accuracy : 0.5;
    var foeMax = mr ? mr.maxHit : 1;
    var incomingPerSwing = foeAcc * (1 + foeMax) / 2;
    var swingsPerKill = Math.max(1, killTimeS / swingS);
    var retaliationShare = Math.max(0, (swingsPerKill - 1) / swingsPerKill);
    var incomingDps = incomingPerSwing * retaliationShare / swingS;

    var hp = (G && G.playerHp > 0) ? G.playerHp : ((G && G.playerMaxHp) || 1);
    var maxHp = (G && G.playerMaxHp > 0) ? G.playerMaxHp : hp;
    var pool = 0, foodId = G && G.foodSlot;
    var owns = (typeof hasTrait === 'function') && hasTrait('auto_eat');
    if(owns && foodId && window.ITEMS && window.ITEMS[foodId] && window.ITEMS[foodId].heals > 0){
      /* A heal is wasted above the bar, so one food is worth at most a full
         bar — otherwise 60 shrimp on a 10 HP character reads as 180 kills. */
      pool = (G.inventory[foodId] || 0) * Math.min(window.ITEMS[foodId].heals, maxHp);
    }
    var effectiveHp = Math.max(1, hp + pool);
    /* An unhittable foe (accuracy or max hit resolved to 0) means the fight
       never ends you. Report the honest infinity as "survives the hour" rather
       than dividing by zero into NaN and printing "—". */
    var survivalSeconds = incomingDps > 0 ? (effectiveHp / incomingDps) : Infinity;
    var survivalKills = Math.floor(Math.min(survivalSeconds, 3600 * 24) / Math.max(0.001, killTimeS));
    return { incomingDps: incomingDps, effectiveHp: effectiveHp,
      survivalKills: survivalKills, survivalSeconds: survivalSeconds };
  }
  /* Published for the suite. LICENCE-7 asserts the acceptance criterion
     against the REAL estimator rather than a re-implementation of it — a
     test that recomputes the formula it is testing proves only that the
     tester can copy. */
  window._hrEstimateCombat = estimateCombat;

  function getMonsterIcon(id){
    var path = window._monsterIcon && window._monsterIcon[id];
    var m = window.MONSTERS && window.MONSTERS[id];
    if(path) return '<img src="'+path+'" alt="" />';
    return '<span style="font-size:calc(96px * var(--ui-scale, 1))">'+(m && m.icon || '👾')+'</span>';
  }

  function lootRowHtml(d){
    var id = typeof d === 'string' ? d : d.id;
    var item = window.ITEMS && window.ITEMS[id];
    var name = item ? (item.n||id) : id;
    var icon = item && item.icon ? item.icon : '📦';
    var iconPath = window._itemPath && window._itemPath[id];
    var iconHtml = iconPath ? '<img src="'+iconPath+'" />' : '<span>'+icon+'</span>';
    /* Wave 1 (audit fix): monster drops carry `ch` (0..1) and no `qty`. The old
       code read `d.chance`/`d.qty`, which monster rows never have, so EVERY drop
       rendered as "1× common" — the rarity structure was invisible at the exact
       moment the player decides what to farm. Read the real chance, show a real
       percentage, and band it so rares read as rare. */
    var ch = (typeof d === 'object')
      ? (typeof d.ch === 'number' ? d.ch : (typeof d.chance === 'number' ? d.chance : null))
      : null;
    var chanceStr, band = 'mp-common';
    if(ch == null){ chanceStr = '—'; band = ''; }
    else if(ch >= 1){ chanceStr = 'Always'; band = 'mp-always'; }
    else {
      var pct = ch * 100;
      chanceStr = (pct < 1 ? pct.toFixed(1) : Math.round(pct)) + '%';
      band = 'mp-' + ((typeof dropBand==='function') ? dropBand(ch) : (ch<=0.05?'rare':(ch<=0.15?'uncommon':'common')));  // Wave 4: shared bands
    }
    var qtyStr = (typeof d === 'object' && d.qty) ? (d.qty[0] === d.qty[1] ? d.qty[0] : d.qty.join('-')) + '× · ' : '';
    return '<div class="mp-loot-row">'+
      '<div class="mp-loot-icon">'+iconHtml+'</div>'+
      '<div class="mp-loot-name">'+name+'</div>'+
      '<div class="mp-loot-meta '+band+'">'+qtyStr+chanceStr+'</div>'+
    '</div>';
  }

  /* "≈5 kills · ≈75s" or the hourly pair — never both, and never the hourly
     pair for a character who cannot reach the hour. An hourly rate quoted at
     someone with a ninety-second life expectancy is not a pessimistic
     estimate, it is a category error, so below the hour the rows are REPLACED
     rather than annotated. (b341, §4.1.) */
  function forecastRateRows(est){
    if(est.survivesAnHour){
      return '<div><span>Kills / hr</span><b>'+fmtNum(est.killsHr)+'</b></div>'+
             '<div><span>XP / hr</span><b>'+fmtNum(est.xpHr)+'</b></div>'+
             '<div><span>You last</span><b>'+fmtRunTime(est.survivalSeconds)+'</b></div>';
    }
    return '<div><span>You last</span><b>≈'+fmtNum(est.survivalKills)+' kills</b></div>'+
           '<div><span>This run</span><b>≈'+fmtRunTime(est.survivalSeconds)+' · ≈'+fmtNum(est.runXp)+' XP</b></div>';
  }
  function fmtRunTime(s){
    if(!isFinite(s)) return '—';
    if(s < 90) return Math.round(s)+'s';
    if(s < 3600) return Math.round(s/60)+'m';
    var h=Math.floor(s/3600), mm=Math.round((s%3600)/60);
    return h+'h'+(mm?' '+mm+'m':'');
  }
  /* The Away line. ALWAYS present, three states, and each one names the thing
     that actually ends the night — the licence, then death, then food. The
     player's question at this screen is "can I leave this running?", and the
     preview never answered it at all before. */
  function awayLineHtml(est){
    var L = (window.HearthriseLicence) ? window.HearthriseLicence.check(G) : {ok:true,kills:0,need:0};
    if(!L.ok){
      return '<b>Away:</b> not yet — land '+L.need+' kills for your Field Licence. '+
             '<b>'+L.kills+' / '+L.need+'.</b>';
    }
    var owns = (typeof hasTrait === 'function') && hasTrait('auto_eat');
    var foodId = G && G.foodSlot;
    if(!owns || !foodId || !(G.inventory[foodId] > 0)){
      return '<b>Away:</b> about <b>'+fmtNum(est.survivalKills)+' kills</b>, then you fall and the '+
             'fight ends. Auto-Eat keeps it running.';
    }
    var capMs = (typeof offlineCapHours === 'function') ? offlineCapHours()*3600000 : 12*3600000;
    var foodMs = est.survivalSeconds * 1000;
    var bound = Math.min(capMs, foodMs);
    var name = (window.ITEMS && window.ITEMS[foodId] && window.ITEMS[foodId].n) || foodId;
    return '<b>Away:</b> about <b>'+fmtRunTime(bound/1000)+'</b>, '+
      (foodMs <= capMs
        ? 'on '+fmtNum(G.inventory[foodId])+' '+name+'.'
        : 'your '+offlineCapHours()+'h offline max, not your food.');
  }

  function renderPreview(monsterId){
    ensureModal();
    var m = window.MONSTERS && window.MONSTERS[monsterId];
    if(!m) return;
    var ov = document.getElementById('mob-preview');
    var modal = document.getElementById('mp-modal');
    var est = estimateCombat(m);
    var weaknessLabel = m.weaponWeak ? m.weaponWeak.charAt(0).toUpperCase()+m.weaponWeak.slice(1) : 'None';
    var weaknessTag = est.weaknessBonus > 1 ? '<span class="mp-tag good">+20% dmg</span>' : '<span class="mp-tag muted">no bonus</span>';
    var atkLv = (typeof getLevel === 'function') ? getLevel('attack') : 1;
    var strLv = (typeof getLevel === 'function') ? getLevel('strength') : 1;
    var defLv = (typeof getLevel === 'function') ? getLevel('defense') : 1;
    var hpLv = (typeof getLevel === 'function') ? getLevel('hitpoints') : 1;
    var rngLv = (typeof getLevel === 'function') ? getLevel('ranged') : 1;
    var magLv = (typeof getLevel === 'function') ? getLevel('magic') : 1;
    var foodId = G && G.foodSlot;
    var foodCount = foodId ? (G.inventory[foodId]||0) : 0;
    var foodIcon = foodId && window.ITEMS[foodId] ? window.ITEMS[foodId].icon : '🍖';
    var foodName = foodId && window.ITEMS[foodId] ? window.ITEMS[foodId].n : 'No food';

    modal.innerHTML = `
      <button class="mp-close" aria-label="Close">✕</button>
      <div class="mp-header">
        <div class="mp-portrait">${getMonsterIcon(monsterId)}</div>
        <div class="mp-title">
          <h2>${m.name}</h2>
          <div class="mp-sub">${m.family||'monster'} · Tier ${m.tier||1}</div>
        </div>
      </div>

      <div class="mp-stats-row">
        <div class="mp-stat-card">
          <div class="mp-stat-label">HP</div>
          <div class="mp-stat-val">${m.hp}</div>
        </div>
        <div class="mp-stat-card">
          <div class="mp-stat-label">Attack</div>
          <div class="mp-stat-val">${m.atk||0}</div>
        </div>
        <div class="mp-stat-card">
          <div class="mp-stat-label">Defense</div>
          <div class="mp-stat-val">${m.def||0}</div>
        </div>
        <div class="mp-stat-card">
          <div class="mp-stat-label">XP / Kill</div>
          <div class="mp-stat-val">${m.xp||0}</div>
        </div>
      </div>

      <div class="mp-info-row">
        <div><span class="mp-info-label">Weakness</span><span class="mp-info-val">${weaknessLabel} ${weaknessTag}</span></div>
        <div><span class="mp-info-label">Attack speed</span><span class="mp-info-val">${((typeof combatTickMs==='function'?combatTickMs():((window.COMBAT_BALANCE&&window.COMBAT_BALANCE.tickMs)||2400))/1000).toFixed(2)}s</span></div>
      </div>

      <div class="mp-grid">
        <div class="mp-pane">
          <h4>Your Combat</h4>
          <div class="mp-mystats">
            <div><span>⚔️</span><b>Lv ${atkLv}</b><small>Attack</small></div>
            <div><span>💪</span><b>Lv ${strLv}</b><small>Strength</small></div>
            <div><span>🛡️</span><b>Lv ${defLv}</b><small>Defense</small></div>
            <div><span>❤️</span><b>Lv ${hpLv}</b><small>HP</small></div>
            <div><span>🏹</span><b>Lv ${rngLv}</b><small>Ranged</small></div>
            <div><span>🧙</span><b>Lv ${magLv}</b><small>Magic</small></div>
          </div>
        </div>
        <div class="mp-pane">
          <h4>Forecast</h4>
          <div class="mp-forecast">
            <div><span>DPS</span><b>${est.dps.toFixed(1)}</b></div>
            <div><span>Hit chance</span><b>${Math.round(est.hitChance*100)}%</b></div>
            <div><span>Damage</span><b>${est.minHit}–${est.maxHit}</b></div>
            <div><span>Time to kill</span><b>${est.killTimeS.toFixed(1)}s</b></div>
            ${forecastRateRows(est)}
          </div>
          <div class="mp-away-line">${awayLineHtml(est)}</div>
        </div>
      </div>

      <div class="mp-pane mp-loot-pane">
        <h4>Loot Table (${(m.drops||[]).length})</h4>
        <div class="mp-loot-grid">${(m.drops||[]).map(lootRowHtml).join('') || '<div class="mp-empty">No drops.</div>'}</div>
      </div>

      <div class="mp-footer">
        <div class="mp-food">
          <div class="mp-food-icon">${foodIcon}</div>
          <div class="mp-food-info">
            <div class="mp-food-name">${foodName}</div>
            <div class="mp-food-qty">${foodCount} in pack</div>
          </div>
        </div>
        <div class="mp-actions">
          <button class="mp-btn mp-btn-secondary" data-act="close">Leave</button>
          <button class="mp-btn mp-btn-primary" data-act="fight" data-monster="${monsterId}">⚔️  Fight</button>
        </div>
      </div>
    `;

    modal.querySelector('.mp-close').addEventListener('click', closePreview);
    modal.querySelectorAll('[data-act=close]').forEach(function(b){ b.addEventListener('click', closePreview); });
    modal.querySelector('[data-act=fight]').addEventListener('click', function(){
      var id = this.dataset.monster;
      closePreview();
      if(typeof window.startCombat === 'function') window.startCombat(id);
    });

    ov.classList.add('open');
  }
  window.openMobPreview = renderPreview;
  /* Wave 1: test seams so the smoke suite can assert the preview reads the real
     engine (forecast) and the real drop chances (loot rows). */
  window.__estimateCombat = estimateCombat;
  window.__lootRowHtml = lootRowHtml;

  /* ══════════════════════════════════════════════════════════════════════
     MONSTER ROW DELEGATION (b341)

     A monster row opens the PREVIEW. It has never been allowed to start a
     fight on one tap — the preview is the only place a player sees what the
     foe hits for before standing in front of it.

     That rule used to be enforced by re-wiring: two independent walkers
     (`rewireRows` here and `rewireMonsterRows` in the monster-detail block)
     each stripped the row's inline `onclick="startCombat(id)"` after every
     render, hooked on `renderMonsterList` and on `showTab('combat')`. Both
     hooks were wrappers around `window.renderMonsterList`, and
     src/features/combat-render.js later REPLACES that global outright and
     calls its own module-local copy from the tier-chip handler — a render
     path neither wrapper could see. So pressing any Tier chip repainted the
     list with live inline handlers, and the next tap started the fight:
     measured 3/3, a Combat-Lv-3 character one-tapped a Green Dragon and died
     within six seconds, and mid-fight it went slime → lich → dead with no
     confirmation.

     A third wrapper would have been a third thing to forget. Instead the rows
     no longer carry a handler at all (they carry `data-monster`), and ONE
     delegated listener on `#panel-combat` — a static element in index.html
     that no renderer replaces — owns every row click, however the list came to
     be painted. Same shape as the b334 combat-style picker fix.

     Delegation on the PANEL rather than on `#monster-list` is deliberate: the
     list's innerHTML is rewritten constantly, and a listener on a node that
     gets replaced is the class of bug this is retiring.

     b342 — THE SELECTOR IS `[data-monster]`, NOT `.monster-row`. b341 fixed
     the rows and left the arena's "Recommended" card, which is the single most
     likely first click in the game, still carrying an inline startCombat().
     Scoping the rule to a CLASS meant every new way of naming a monster on
     this panel had to remember to opt in; scoping it to the DATA means the
     rule is "anything on the combat panel that names a foe opens that foe's
     preview", which is the sentence we actually mean and which the next
     surface gets for free. The preview overlay is appended to <body>, not to
     this panel, so its own Fight button is unaffected.
     ══════════════════════════════════════════════════════════════════════ */
  document.addEventListener('click', function(e){
    var t = e.target;
    if(!t || typeof t.closest !== 'function') return;
    var row = t.closest('#panel-combat [data-monster]');
    if(!row || row.disabled) return;
    var id = row.getAttribute('data-monster');
    if(!id) return;
    e.preventDefault(); e.stopPropagation();
    // Tapping the foe you are already fighting stops the fight (unchanged).
    if(window.G && window.G.activeMonster === id){
      if(typeof window.stopCombat === 'function') window.stopCombat();
      return;
    }
    renderPreview(id);
  }, true);

  // Esc to close
  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape') closePreview();
  });

  console.log('Combat preview: loaded');
})();

