/* ─── Daily Goals (3 quests, refresh per UTC day) ─── */
var DAILY_GOAL_POOL = [
  {id:'kill_any',  emoji:'⚔️', name:'Slay 10 monsters',   target:10, source:'stats.kills'},
  {id:'kill_more', emoji:'🩸', name:'Slay 30 monsters',   target:30, source:'stats.kills'},
  /* b226 (spec §8.2) — these three read PER-SKILL counters, not item-specific
     collection counters. They used to point at collection.normal_log /
     collection.copper_ore / collection.shrimp, so a level-90 woodcutter
     chopping Duskwood made zero progress on "Gather 25 logs" and "Catch 15
     fish" was unachievable for anyone past Shrimp unless they deliberately
     downgraded. A daily that gets harder the better you are is backwards. */
  {id:'gather_logs', emoji:'🪵', name:'Gather 25 logs',  target:25, source:'stats.chopped'},
  {id:'mine_ore',  emoji:'⛏️', name:'Mine 25 ores',      target:25, source:'stats.mined'},
  {id:'cook',      emoji:'🍳', name:'Cook 5 dishes',     target:5,  source:'stats.cooked'},
  {id:'fish',      emoji:'🎣', name:'Catch 15 fish',     target:15, source:'stats.fished'},
  {id:'gold_500',  emoji:'🪙', name:'Earn 500 gold',     target:500, source:'_dailyGoldDelta'},
  {id:'plant',     emoji:'🌾', name:'Plant 5 crops',     target:5,  source:'stats.planted'},
  {id:'level_up',  emoji:'📈', name:'Gain a skill level', target:1,  source:'stats.levelups'},
];
function getGoalsForToday(){
  var key = todayKey();
  if(!G.dailyGoals || G.dailyGoals.dayKey !== key){
    // Pick 3 deterministic goals based on day
    var seed = key;
    var picks = []; var used = {};
    for(var i = 0; i < 3; i++){
      seed = (seed * 9301 + 49297) % 233280;
      var idx = Math.floor((seed/233280) * DAILY_GOAL_POOL.length);
      while(used[idx]) idx = (idx+1) % DAILY_GOAL_POOL.length;
      used[idx] = true; picks.push(DAILY_GOAL_POOL[idx]);
    }
    G.dailyGoals = {dayKey: key, picks: picks.map(function(g){return g.id;}), startValues: {}};
    picks.forEach(function(g){
      G.dailyGoals.startValues[g.id] = readSource(g.source);
    });
  }
  return G.dailyGoals.picks.map(function(id){
    return DAILY_GOAL_POOL.find(function(p){return p.id===id;});
  }).filter(Boolean);
}
// b130: explicit window assignment so the Quests modal renderer in
// the wrapped IIFE below can find it. Same fix pattern as b127's
// hoursTillUTCMidnight — function declarations don't reach window
// from inside nested IIFEs.
window.getGoalsForToday = getGoalsForToday;
/* b226: the pool itself, so the suite can assert what each goal READS. The
   sources are the fix — a goal that watches one item id is the bug. */
window.DAILY_GOAL_POOL = DAILY_GOAL_POOL;

/* b224 (LIVE HOTFIX) — the quests-never-tick bug.
   readSource() is declared INSIDE this IIFE (block 16). The Quests strip +
   modal live in their own IIFE (block 40) and referenced it bare, guarded by
   `if(typeof readSource !== 'function') return 0;`. That guard never threw — it
   just returned 0 — so every daily and weekly quest reported 0 / N forever and
   nothing was ever claimable, with nothing in the console to show for it.
   Exactly the cross-IIFE trap b127 (hoursTillUTCMidnight) and b130
   (getGoalsForToday) already fixed here; readSource was the third read out of
   this scope and the only one whose failure was silent. Export it.
   The smoke suite now asserts a real player counter moves the RENDERED number,
   so an export can never quietly go missing again. */
function readSource(path){
  if(!G) return 0;
  /* `_dailyGoldDelta` is a derived source, not a path into G — without this the
     "Earn 500 gold" daily read G._dailyGoldDelta (undefined → 0) and stayed at
     0 even once the renderer could see it. readPath() (block 17) already
     derives it exactly this way. */
  /* b292: ONE definition of daily gold income — delegate, never re-derive. Three
     copies of this maths existed and the goal read a net-balance one. */
  if(path === '_dailyGoldDelta') return (typeof window._dailyGoldDelta === 'function')
    ? window._dailyGoldDelta()
    : Math.max(0, (G.gold||0) - ((G.dailyGoldStart||{}).gold||0));
  var parts = path.split('.');
  var cur = G;
  for(var i = 0; i < parts.length; i++){
    if(cur == null) return 0;
    cur = cur[parts[i]];
  }
  return cur || 0;
}
window.readSource = readSource;
function renderDailyGoals(host){
  if(!host) return;
  var goals = getGoalsForToday();
  host.innerHTML = '<div class="card"><div class="card-head"><div class="card-title">Daily Goals</div><span class="card-sub">Resets at UTC midnight</span></div><div class="card-body"><div class="daily-goals">' +
    goals.map(function(g){
      var startVal = (G.dailyGoals.startValues||{})[g.id] || 0;
      var current = Math.max(0, readSource(g.source) - startVal);
      var done = current >= g.target;
      return '<div class="daily-goal'+(done?' done':'')+'">'+
        '<span class="dg-emoji">'+g.emoji+'</span>'+
        '<div class="dg-text"><b>'+g.name+'</b><span>'+(done?'Complete!':'Resets in ' + hoursTillUTCMidnight() + 'h')+'</span></div>'+
        '<span class="dg-progress">'+Math.min(current,g.target)+' / '+g.target+'</span>'+
      '</div>';
    }).join('') + '</div></div></div>';
}
function hoursTillUTCMidnight(){
  var d = new Date(); return Math.max(1, 24 - d.getUTCHours());
}
// b127: explicit window assignment. Function declarations at the top
// of legacy.js don't always reach `window` from inside the quests-modal
// IIFE, so the renderer fell through to the '?' fallback and rendered
// "Resets in ?h" forever.
window.hoursTillUTCMidnight = hoursTillUTCMidnight;

