/* ─── Artisan render: replaces 'Train by fighting' empty state ─── */
window.renderArtisanActivities = function(skillId){
  var recipes = window.ARTISAN_RECIPES[skillId];
  if(!recipes || typeof getLevel !== 'function') return '';
  var lv = getLevel(skillId);
  return recipes.map(function(r){
    var have = (G.inventory && G.inventory[r.input]) || 0;
    var unlocked = lv >= r.req;
    var canDo = unlocked && have > 0;
    var active = G.activeSkill===skillId && G.skillTargetId===r.id;
    var inputName = (typeof ITEMS!=='undefined' && ITEMS[r.input]) ? ITEMS[r.input].n : r.input;
    var outputLabel = r.output && typeof ITEMS!=='undefined' && ITEMS[r.output] ? ITEMS[r.output].n : (r.output||'XP only');
    var status = '';
    if(!unlocked) status = '<span class="muted tiny">🔒 Lv '+r.req+'</span>';
    else if(!have) status = '<span class="muted tiny">Need '+inputName+'</span>';
    else if(active) status = '<span class="mr-active">Active</span>';
    var secondaryText = '';
    if(r.secondary){
      secondaryText = ' + ' + Object.entries(r.secondary).map(function(kv){
        var nm = (ITEMS[kv[0]]&&ITEMS[kv[0]].n)||kv[0];
        return kv[1]+'×'+nm;
      }).join(', ');
    }
    return '<button class="monster-row '+(active?'fighting':'')+'" '+(canDo?'':'disabled')+' onclick="'+(active?'stopSkill()':"window.startArtisan('"+skillId+"','"+r.id+"')")+'">'+
      '<span class="mi">'+r.icon+'</span>'+
      '<div style="flex:1;min-width:0"><span class="mn">'+r.name+'</span><span class="ms">Lv '+r.req+' · '+Math.max(1,Math.floor(window.pacedXp(skillId,r.xp)))+' XP · '+(window.pacedActionMs(r.ms)/1000).toFixed(1)+'s · ('+inputName+secondaryText+(r.output?' → '+outputLabel:'')+') · Have: '+have+'</span></div>'+
      status+
    '</button>';
  }).join('');
};

/* ─── Artisan action loop (mirrors startSkill but consumes inputs) ─── */
window.startArtisan = function(skillId, recipeId){
  var recipes = window.ARTISAN_RECIPES[skillId];
  if(!recipes) return;
  var r = recipes.find(function(x){return x.id===recipeId;});
  if(!r) return;
  if(getLevel(skillId) < r.req){ if(typeof notify==='function') notify('Need Lv '+r.req+' '+skillId,'kill'); return; }
  if(!(G.inventory[r.input] > 0)){ if(typeof notify==='function') notify('No '+(ITEMS[r.input]?.n||r.input),'kill'); return; }
  if(typeof stopSkill === 'function') stopSkill();
  G.activeSkill = skillId; G.skillTargetId = recipeId; G.skillProgress = 0;
  G.skillMs = artisanIntervalMs(skillId, r);
  window._armArtisanTimers(G.skillMs);
  if(typeof renderSkillsList==='function') renderSkillsList();
  if(typeof renderSkillDetail==='function') renderSkillDetail(skillId);
};

/* b227: ONE place that arms the artisan timers, so retimeActivity() can swap
   the interval mid-session without duplicating the loop bodies — and so the
   two startArtisan definitions in this file (the base one above and the
   inputs-aware override further down) cannot drift apart again. They read
   G.activeSkill / G.skillTargetId rather than closing over arguments, because
   by the time a retime fires those are the authority on what is running. */
window._armArtisanTimers = function(ms){
  if(window._artisanInterval) clearInterval(window._artisanInterval);
  if(window._artisanProgress) clearInterval(window._artisanProgress);
  window._artisanInterval = setInterval(function(){ doArtisanAction(G.activeSkill, G.skillTargetId); }, ms);
  window._artisanProgress = setInterval(function(){
    G.skillProgress = Math.min(1, G.skillProgress + (100/ms));
    if((typeof window.isSkillsVisible==='function' ? window.isSkillsVisible() : (typeof activeTab !== 'undefined' && activeTab==='skills')) && typeof renderSkillDetail==='function') renderSkillDetail(G.activeSkill);
  }, 100);
};
/* b201: each artisan skill reads its own workbench-room speed bonus. Routed
   through the shared activityIntervalMs() so the live loop, the retimer and
   the offline replay all compute the identical number from one formula. */
function artisanIntervalMs(skillId, r){
  var ms = (typeof window.activityIntervalMs === 'function') ? window.activityIntervalMs() : null;
  if(ms != null) return ms;
  var bonusKey = ({cooking:'cookSpeed', smithing:'smithSpeed', crafting:'craftSpeed', prayer:'prayerSpeed'})[skillId] || 'gatherSpeed';
  var speed = (typeof getBonus==='function') ? getBonus(bonusKey) : 0;
  return Math.max(500, Math.floor(window.pacedActionMs(r.ms) * (1 - speed)));
}

window.doArtisanAction = function(skillId, recipeId){
  var recipes = window.ARTISAN_RECIPES[skillId];
  var r = recipes && recipes.find(function(x){return x.id===recipeId;});
  if(!r) return;
  /* Out of input or secondary? Stop. */
  if(!(G.inventory[r.input] > 0)){ window._stopArtisan(); return; }
  if(r.secondary){
    var oot = false;
    Object.entries(r.secondary).forEach(function(kv){ if((G.inventory[kv[0]]||0) < kv[1]) oot = true; });
    if(oot){ window._stopArtisan(); if(typeof notify==='function') notify('Out of secondary materials','kill'); return; }
  }
  /* Consume */
  if(typeof removeItem==='function') removeItem(r.input, 1);
  if(r.secondary) Object.entries(r.secondary).forEach(function(kv){ removeItem(kv[0], kv[1]); });
  /* Produce */
  if(r.output && typeof addItem==='function') addItem(r.output, 1);
  /* XP */
  if(typeof addXp==='function') addXp(skillId, r.xp);
  /* Counters */
  if(skillId==='cooking'){
    G.stats.cooked = (G.stats.cooked||0) + 1;
    if(typeof updateDaily==='function') updateDaily('cooked', 1);
    // b217: onboarding chain routes new players through cooking BEFORE combat
    // (the "Cook 5 dishes" prep quest), so mirror the counter into updateQuest.
    if(typeof updateQuest==='function') updateQuest('cooked', 1);
  }
  if(skillId==='smithing'){
    G.stats.refined = (G.stats.refined||0) + 1;
    G.stats.smithed = (G.stats.smithed||0) + 1;
    if(typeof updateDaily==='function') updateDaily('smithed', 1);
  }
  if(skillId==='crafting'){
    G.stats.refined = (G.stats.refined||0) + 1;
    G.stats.crafted = (G.stats.crafted||0) + 1;
    if(typeof updateDaily==='function') updateDaily('crafted', 1);
  }
  if(typeof renderSkillDetail==='function') renderSkillDetail(skillId);
  if(typeof updateTopbar==='function') updateTopbar();
};

/* Hook into existing stopSkill so we also clear artisan intervals */
window._stopArtisan = function(){
  if(window._artisanInterval){ clearInterval(window._artisanInterval); window._artisanInterval=null; }
  if(window._artisanProgress){ clearInterval(window._artisanProgress); window._artisanProgress=null; }
};
(function(){
  var origStop = window.stopSkill;
  if(typeof origStop !== 'function') return;
  window.stopSkill = function(){
    window._stopArtisan();
    return origStop.apply(this, arguments);
  };
})();

/* ─── Daily gold-today tracking ─── */
(function(){
  if(typeof G !== 'object' || !G) return;
  function todayKey(){ var d=new Date(); return d.getUTCFullYear()*10000+(d.getUTCMonth()+1)*100+d.getUTCDate(); }
  function checkDailyGold(){
    if(typeof G !== 'object') return;
    var today = todayKey();
    if(!G.dailyGoldStart || G.dailyGoldStart.day !== today){
      G.dailyGoldStart = {day: today, gold: G.gold||0, earned: 0};
    }
    if(typeof G.dailyGoldStart.earned !== 'number') G.dailyGoldStart.earned = 0;
  }
  setTimeout(checkDailyGold, 200);
  setInterval(checkDailyGold, 60000);

  /* b292 (paione: "I sold about 10k in items didn't get the quest to earn 500 gold").
     "Earn 500 gold" measured `G.gold - goldAtDayStart` — a NET BALANCE delta, not
     income. Sell 10,000g and then spend it (gear, bank space, seeds) and your net is
     flat, so the quest paid nothing even though you plainly earned the gold. Gold is
     added from eight different places, so instead of touching every call site we
     accumulate only the POSITIVE changes — real income, from any source, and spending
     can never claw it back. */
  var _goldSeen = null;
  setInterval(function(){
    if(typeof G !== 'object' || !G) return;
    var g = G.gold || 0;
    if(_goldSeen === null){ _goldSeen = g; return; }
    if(g > _goldSeen){
      checkDailyGold();
      G.dailyGoldStart.earned = (G.dailyGoldStart.earned || 0) + (g - _goldSeen);
    }
    _goldSeen = g;
  }, 500);
})();

// ===== block 19: goldfix-js =====
(function(){
  var origRead = window.readPath;
  window._dailyGoldDelta = function(){
    if(!G || !G.dailyGoldStart) return 0;
    /* b292: prefer REAL income (accumulated positive gold changes) over the old
       net-balance delta, so selling then spending still counts. Falls back to the
       old maths for a save that predates the counter. */
    var earned = G.dailyGoldStart.earned;
    if(typeof earned === 'number') return Math.max(0, earned);
    return Math.max(0, (G.gold||0) - (G.dailyGoldStart.gold||0));
  };
})();

