(function(){
  // The skill-progress interval ticks renderSkillDetail(G.activeSkill) every 100ms,
  // forcibly snapping the panel back to the active skill. We track the user's
  // intended view separately and short-circuit engine-driven calls.
  // 
  // CRITICAL: this script must wrap renderSkillDetail AFTER activities-grid
  // patches it (which happens at DOMContentLoaded + 100ms). We wait 600ms.
  function applyFix(){
    if(typeof window.renderSkillDetail !== 'function') return;
    if(typeof window.openSkillDetail !== 'function') return;
    if(window.__viewOtherSkillsApplied) return;
    window.__viewOtherSkillsApplied = true;

    window.__viewedSkillId = window.__viewedSkillId || null;

    var origOpen = window.openSkillDetail;
    window.openSkillDetail = function(id){
      window.__viewedSkillId = id;
      var ret = origOpen.apply(this, arguments);
      // b130: On mobile (single-column layout), the skill-detail panel
      // renders BELOW the skills-list. Clicking a tile gave no visible
      // feedback — players didn't realise the detail had loaded
      // hundreds of pixels down. Auto-scroll the detail into view on
      // narrow viewports so the click is acknowledged.
      try {
        if (window.innerWidth <= 540 || (window.innerHeight <= 540 && window.innerWidth <= 1024)) {
          var d = document.getElementById('skill-detail');
          if (d && typeof d.scrollIntoView === 'function') {
            // rAF to let the renderSkillDetail innerHTML complete first.
            requestAnimationFrame(function(){
              try { d.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch(e){}
            });
          }
        }
      } catch(e){}
      return ret;
    };

    var origRender = window.renderSkillDetail;
    window.renderSkillDetail = function(id){
      var viewed = window.__viewedSkillId;
      var calledForActive = (typeof G !== 'undefined' && G.activeSkill === id);
      // Engine-driven re-render for the active skill, but user is viewing a different skill: skip.
      if(viewed && viewed !== id && calledForActive){
        return;
      }
      if(!viewed) window.__viewedSkillId = id;
      return origRender.apply(this, arguments);
    };

    console.log('[View-other-skills fix] applied');
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(applyFix, 600); });
  } else {
    setTimeout(applyFix, 600);
  }
})();

